//! Named fixture registry shared by the fixture generator, the golden
//! generator and the tests.
//!
//! Every fixture builds its exact bytes from code; no binary capture is
//! checked in other than the generated files.

use std::path::{Path, PathBuf};

use crate::compress;
use crate::pcap;
use crate::pcapng;
use crate::tls;
use crate::wire::{ByteOrder, LINKTYPE_ETHERNET, Timestamp, TimestampResolution};

/// A generated capture file and the golden cases that exercise it.
#[derive(Clone, Copy, Debug)]
pub struct Fixture {
    /// Stable fixture name, used as the golden directory name.
    pub name: &'static str,
    /// File extension, without the leading dot.
    pub extension: &'static str,
    builder: fn() -> Result<Vec<u8>, String>,
    case_specs: &'static [CaseSpec],
}

impl Fixture {
    /// The fixture's file name, including its extension.
    pub fn file_name(&self) -> String {
        format!("{}.{}", self.name, self.extension)
    }

    /// The fixture's path relative to the repository root.
    pub fn relative_path(&self) -> String {
        format!("tests/fixtures/{}", self.file_name())
    }

    /// Build the fixture's exact bytes.
    pub fn build(&self) -> Result<Vec<u8>, String> {
        (self.builder)()
    }

    /// The golden cases for this fixture, with the fixture path substituted
    /// into each argument vector.
    pub fn cases(&self) -> Vec<GoldenCase> {
        let path = self.relative_path();
        let hosts = crate::golden::fixtures_dir().join("names-hosts.txt");
        let hosts = hosts.to_string_lossy().into_owned();
        self.case_specs
            .iter()
            .chain(extra_case_specs(self.name).iter())
            .map(|spec| GoldenCase {
                id: spec.id,
                args: spec
                    .args
                    .iter()
                    .map(|argument| {
                        argument
                            .replace("{fixture}", &path)
                            .replace("{hosts}", &hosts)
                    })
                    .collect(),
                capture: None,
            })
            .collect()
    }

    /// The golden cases with paths for `{output}` and `{scratch}` substituted.
    ///
    /// `{output}` marks a capture file the case must produce; the resolved
    /// path is returned in [`GoldenCase::capture`]. `{scratch}` is a path the
    /// case may write but whose bytes are not compared, used by failure cases
    /// that still need a write target.
    pub fn cases_with_paths(&self, output: &Path, scratch: &Path) -> Vec<GoldenCase> {
        let path = self.relative_path();
        let hosts = crate::golden::fixtures_dir().join("names-hosts.txt");
        let hosts = hosts.to_string_lossy().into_owned();
        let output = output.to_string_lossy();
        let scratch = scratch.to_string_lossy();
        self.case_specs
            .iter()
            .chain(extra_case_specs(self.name).iter())
            .map(|spec| {
                let mut capture = None;
                let args = spec
                    .args
                    .iter()
                    .map(|argument| {
                        let mut resolved = argument
                            .replace("{fixture}", &path)
                            .replace("{hosts}", &hosts);
                        if resolved.contains("{output}") {
                            resolved = resolved.replace("{output}", &output);
                            capture = Some(PathBuf::from(&resolved));
                        }
                        resolved.replace("{scratch}", &scratch)
                    })
                    .collect();
                GoldenCase {
                    id: spec.id,
                    args,
                    capture,
                }
            })
            .collect()
    }
}

/// One golden case: its name and the exact command-line arguments that produce it.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct GoldenCase {
    /// Case id, used as the golden file stem.
    pub id: &'static str,
    /// Command-line arguments, with the fixture path already resolved.
    pub args: Vec<String>,
    /// Capture file this case must produce, when its arguments contain
    /// `{output}`.
    pub capture: Option<PathBuf>,
}

#[derive(Debug)]
struct CaseSpec {
    id: &'static str,
    args: &'static [&'static str],
}

/// Arguments for a `-T fields` case over the field-output fixture.
///
/// The fixed options and fields keep every case focused on the `-E`, `-c`,
/// `-l`, `-q` or `-Q` form under test.
macro_rules! field_output_args {
    ($($option:expr),* $(,)?) => {
        &[
            "-n",
            "-T",
            "fields",
            $($option,)*
            "-e",
            "frame.number",
            "-e",
            "frame.interface_name",
            "-e",
            "eth.addr",
            "-r",
            "{fixture}",
        ]
    };
}

