fn build_tcp_wscale() -> Result<Vec<u8>, String> {
    let client = SOURCE_ADDRESS;
    let server = DESTINATION_ADDRESS;
    let wscale_seven = [0x03, 0x03, 0x07, 0x01];
    let wscale_two = [0x03, 0x03, 0x02, 0x01];
    let frames = vec![
        tcp_frame_v4_window(
            client,
            server,
            TcpFields {
                source_port: 40_000,
                destination_port: 443,
                sequence: 1_000,
                flags: 0x02,
                window: 4_096,
                options: &wscale_seven,
                ..Default::default()
            },
        )?,
        tcp_frame_v4_window(
            server,
            client,
            TcpFields {
                source_port: 443,
                destination_port: 40_000,
                sequence: 5_000,
                acknowledgement: 1_001,
                flags: 0x12,
                window: 2_048,
                options: &wscale_two,
                ..Default::default()
            },
        )?,
        tcp_frame_v4_window(
            client,
            server,
            TcpFields {
                source_port: 40_000,
                destination_port: 443,
                sequence: 1_001,
                acknowledgement: 5_001,
                flags: 0x10,
                window: 4_096,
                ..Default::default()
            },
        )?,
        tcp_frame_v4_window(
            server,
            client,
            TcpFields {
                source_port: 443,
                destination_port: 40_000,
                sequence: 5_001,
                acknowledgement: 1_001,
                flags: 0x18,
                window: 2_048,
                payload: b"hello",
                ..Default::default()
            },
        )?,
        tcp_frame_v4_window(
            client,
            server,
            TcpFields {
                source_port: 40_000,
                destination_port: 443,
                sequence: 1_001,
                acknowledgement: 5_006,
                flags: 0x10,
                window: 4_096,
                ..Default::default()
            },
        )?,
        tcp_frame_v4_window(
            THIRD_ADDRESS,
            server,
            TcpFields {
                source_port: 40_000,
                destination_port: 7_777,
                sequence: 7_777,
                acknowledgement: 8_888,
                flags: 0x18,
                payload: b"mid",
                ..Default::default()
            },
        )?,
        tcp_frame_v4_window(
            server,
            THIRD_ADDRESS,
            TcpFields {
                source_port: 7_777,
                destination_port: 40_000,
                sequence: 8_888,
                acknowledgement: 7_780,
                flags: 0x10,
                ..Default::default()
            },
        )?,
    ];
    timed_link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

fn fixture_prefix(data: &[u8], length: usize) -> &[u8] {
    data.get(..length).unwrap_or_default()
}

fn fixture_suffix(data: &[u8], start: usize) -> &[u8] {
    data.get(start..).unwrap_or_default()
}

fn fixture_middle(data: &[u8], start: usize, end: usize) -> &[u8] {
    data.get(start..end).unwrap_or_default()
}

fn build_tcp_reassembly() -> Result<Vec<u8>, String> {
    let client = SOURCE_ADDRESS;
    let server = DESTINATION_ADDRESS;
    let dns = dns_tcp_payload("example.com");
    let mut frames = Vec::new();
    let handshake = |frames: &mut Vec<Vec<u8>>,
                     port: u16,
                     base: u32,
                     peer: u32,
                     server_port: u16|
     -> Result<(), String> {
        frames.push(tcp_frame_v4_window(
            client,
            server,
            TcpFields {
                source_port: port,
                destination_port: server_port,
                sequence: base,
                flags: 0x02,
                ..Default::default()
            },
        )?);
        frames.push(tcp_frame_v4_window(
            server,
            client,
            TcpFields {
                source_port: server_port,
                destination_port: port,
                sequence: peer,
                acknowledgement: base + 1,
                flags: 0x12,
                ..Default::default()
            },
        )?);
        frames.push(tcp_frame_v4_window(
            client,
            server,
            TcpFields {
                source_port: port,
                destination_port: server_port,
                sequence: base + 1,
                acknowledgement: peer + 1,
                flags: 0x10,
                ..Default::default()
            },
        )?);
        Ok(())
    };
    // Flow 1: a DNS message split between two segments.
    handshake(&mut frames, 40_000, 1_000, 5_000, 53)?;
    frames.push(tcp_frame_v4_window(
        client,
        server,
        TcpFields {
            source_port: 40_000,
            destination_port: 53,
            sequence: 1_001,
            acknowledgement: 5_001,
            flags: 0x18,
            payload: fixture_prefix(&dns, 10),
            ..Default::default()
        },
    )?);
    frames.push(tcp_frame_v4_window(
        client,
        server,
        TcpFields {
            source_port: 40_000,
            destination_port: 53,
            sequence: 1_011,
            acknowledgement: 5_001,
            flags: 0x18,
            payload: fixture_suffix(&dns, 10),
            ..Default::default()
        },
    )?);
    // Flow 2: a DNS message in one segment.
    handshake(&mut frames, 40_001, 2_000, 6_000, 53)?;
    frames.push(tcp_frame_v4_window(
        client,
        server,
        TcpFields {
            source_port: 40_001,
            destination_port: 53,
            sequence: 2_001,
            acknowledgement: 6_001,
            flags: 0x18,
            payload: &dns,
            ..Default::default()
        },
    )?);
    // Flow 3: the tail arrives first and the middle fills the hole.
    handshake(&mut frames, 40_002, 3_000, 7_000, 53)?;
    frames.push(tcp_frame_v4_window(
        client,
        server,
        TcpFields {
            source_port: 40_002,
            destination_port: 53,
            sequence: 3_001,
            acknowledgement: 7_001,
            flags: 0x18,
            payload: fixture_prefix(&dns, 10),
            ..Default::default()
        },
    )?);
    frames.push(tcp_frame_v4_window(
        client,
        server,
        TcpFields {
            source_port: 40_002,
            destination_port: 53,
            sequence: 3_021,
            acknowledgement: 7_001,
            flags: 0x18,
            payload: fixture_suffix(&dns, 20),
            ..Default::default()
        },
    )?);
    frames.push(tcp_frame_v4_window(
        client,
        server,
        TcpFields {
            source_port: 40_002,
            destination_port: 53,
            sequence: 3_011,
            acknowledgement: 7_001,
            flags: 0x18,
            payload: fixture_middle(&dns, 10, 20),
            ..Default::default()
        },
    )?);
    // Flow 4: an overlapping tail with the same bytes.
    handshake(&mut frames, 40_003, 4_000, 8_000, 53)?;
    frames.push(tcp_frame_v4_window(
        client,
        server,
        TcpFields {
            source_port: 40_003,
            destination_port: 53,
            sequence: 4_001,
            acknowledgement: 8_001,
            flags: 0x18,
            payload: fixture_prefix(&dns, 20),
            ..Default::default()
        },
    )?);
    frames.push(tcp_frame_v4_window(
        client,
        server,
        TcpFields {
            source_port: 40_003,
            destination_port: 53,
            sequence: 4_011,
            acknowledgement: 8_001,
            flags: 0x18,
            payload: fixture_suffix(&dns, 10),
            ..Default::default()
        },
    )?);
    // Flow 5: a missing middle never completes the PDU.
    handshake(&mut frames, 40_004, 5_000, 9_000, 53)?;
    frames.push(tcp_frame_v4_window(
        client,
        server,
        TcpFields {
            source_port: 40_004,
            destination_port: 53,
            sequence: 5_001,
            acknowledgement: 9_001,
            flags: 0x18,
            payload: fixture_prefix(&dns, 10),
            ..Default::default()
        },
    )?);
    frames.push(tcp_frame_v4_window(
        client,
        server,
        TcpFields {
            source_port: 40_004,
            destination_port: 53,
            sequence: 5_021,
            acknowledgement: 9_001,
            flags: 0x18,
            payload: fixture_suffix(&dns, 20),
            ..Default::default()
        },
    )?);
    // Flow 6: a TLS record split after its three-byte prefix.
    let tls = tls_handshake_record();
    handshake(&mut frames, 40_005, 6_000, 10_000, 443)?;
    frames.push(tcp_frame_v4_window(
        client,
        server,
        TcpFields {
            source_port: 40_005,
            destination_port: 443,
            sequence: 6_001,
            acknowledgement: 10_001,
            flags: 0x18,
            payload: fixture_prefix(&tls, 3),
            ..Default::default()
        },
    )?);
    frames.push(tcp_frame_v4_window(
        client,
        server,
        TcpFields {
            source_port: 40_005,
            destination_port: 443,
            sequence: 6_004,
            acknowledgement: 10_001,
            flags: 0x18,
            payload: fixture_suffix(&tls, 3),
            ..Default::default()
        },
    )?);
    // Flow 7: an HTTP request split between its header and its body.
    let http = http_request();
    let body_start = http
        .windows(4)
        .position(|window| window == b"\r\n\r\n")
        .map(|index| index + 4)
        .unwrap_or(http.len());
    handshake(&mut frames, 40_006, 7_000, 11_000, 80)?;
    frames.push(tcp_frame_v4_window(
        client,
        server,
        TcpFields {
            source_port: 40_006,
            destination_port: 80,
            sequence: 7_001,
            acknowledgement: 11_001,
            flags: 0x18,
            payload: fixture_prefix(&http, body_start),
            ..Default::default()
        },
    )?);
    frames.push(tcp_frame_v4_window(
        client,
        server,
        TcpFields {
            source_port: 40_006,
            destination_port: 80,
            sequence: 7_001 + u32::try_from(body_start).unwrap_or(0),
            acknowledgement: 11_001,
            flags: 0x18,
            payload: fixture_suffix(&http, body_start),
            ..Default::default()
        },
    )?);
    timed_link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

