fn build_tcp_options() -> Result<Vec<u8>, String> {
    let mss = [0x02, 0x04, 0x05, 0xb4];
    let window_scale = [0x03, 0x03, 0x07, 0x01];
    let sack_permitted = [0x04, 0x02, 0x01, 0x01];
    let mut sack = Vec::new();
    sack.extend_from_slice(&[0x05, 0x0a]);
    sack.extend_from_slice(&2_000_u32.to_be_bytes());
    sack.extend_from_slice(&3_000_u32.to_be_bytes());
    sack.extend_from_slice(&[0x01, 0x01]);
    let mut timestamps = Vec::new();
    timestamps.extend_from_slice(&[0x08, 0x0a]);
    timestamps.extend_from_slice(&0x1122_3344_u32.to_be_bytes());
    timestamps.extend_from_slice(&0x5566_7788_u32.to_be_bytes());
    timestamps.extend_from_slice(&[0x01, 0x01]);
    let unknown = [0x1e, 0x04, 0xaa, 0xbb];
    let invalid_mss = [0x02, 0x05, 0x05, 0xb4, 0x00, 0x00, 0x00, 0x00];
    let unknown_zero = [0x1e, 0x00, 0x01, 0x01];
    let eol_nonzero = [0x00, 0x11, 0x22, 0x33];
    let frames = vec![
        tcp_option_frame(&[0x00, 0x00, 0x00, 0x00])?,
        tcp_option_frame(&[0x01, 0x01, 0x01, 0x01])?,
        tcp_option_frame(&mss)?,
        tcp_option_frame(&window_scale)?,
        tcp_option_frame(&sack_permitted)?,
        tcp_option_frame(&sack)?,
        tcp_option_frame(&timestamps)?,
        tcp_option_frame(&unknown)?,
        tcp_option_frame(&invalid_mss)?,
        tcp_option_frame(&unknown_zero)?,
        tcp_option_frame(&eol_nonzero)?,
    ];
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

fn build_tcp_boundary() -> Result<Vec<u8>, String> {
    let full = tcp_segment(
        4,
        &SOURCE_ADDRESS,
        &DESTINATION_ADDRESS,
        TcpFields {
            source_port: TCP_TEST_SOURCE_PORT,
            destination_port: TCP_TEST_DESTINATION_PORT,
            sequence: 1_000,
            acknowledgement: 2_000,
            flags: 0x18,
            payload: b"hello",
            ..Default::default()
        },
    );
    let mut frames = Vec::new();
    for count in [4_usize, 13, 14, 16, 18, 19] {
        let truncated = full.get(..count).unwrap_or(&[]);
        frames.push(ethernet_frame(0x0800, &ipv4_transport(6, truncated, None)?));
    }
    let short_header = tcp_segment(
        4,
        &SOURCE_ADDRESS,
        &DESTINATION_ADDRESS,
        TcpFields {
            source_port: TCP_TEST_SOURCE_PORT,
            destination_port: TCP_TEST_DESTINATION_PORT,
            sequence: 1_000,
            flags: 0x10,
            data_offset: Some(4),
            ..Default::default()
        },
    );
    let long_header = tcp_segment(
        4,
        &SOURCE_ADDRESS,
        &DESTINATION_ADDRESS,
        TcpFields {
            source_port: TCP_TEST_SOURCE_PORT,
            destination_port: TCP_TEST_DESTINATION_PORT,
            sequence: 1_000,
            flags: 0x10,
            data_offset: Some(15),
            ..Default::default()
        },
    );
    let mss = [0x02, 0x04, 0x05, 0xb4];
    let options_full = tcp_segment(
        4,
        &SOURCE_ADDRESS,
        &DESTINATION_ADDRESS,
        TcpFields {
            source_port: TCP_TEST_SOURCE_PORT,
            destination_port: TCP_TEST_DESTINATION_PORT,
            sequence: 1_000,
            flags: 0x02,
            options: &mss,
            ..Default::default()
        },
    );
    let options_cut_two = options_full.get(..22).unwrap_or(&[]);
    let options_cut_one = options_full.get(..21).unwrap_or(&[]);
    let bad = tcp_segment(
        4,
        &SOURCE_ADDRESS,
        &DESTINATION_ADDRESS,
        TcpFields {
            source_port: TCP_TEST_SOURCE_PORT,
            destination_port: TCP_TEST_DESTINATION_PORT,
            sequence: 1_000,
            acknowledgement: 2_000,
            flags: 0x10,
            checksum: Some(0x1234),
            ..Default::default()
        },
    );
    let zero = tcp_segment(
        4,
        &SOURCE_ADDRESS,
        &DESTINATION_ADDRESS,
        TcpFields {
            source_port: TCP_TEST_SOURCE_PORT,
            destination_port: TCP_TEST_DESTINATION_PORT,
            sequence: 1_000,
            acknowledgement: 2_000,
            flags: 0x10,
            checksum: Some(0),
            ..Default::default()
        },
    );
    let good6 = tcp_segment(
        6,
        &SOURCE_IPV6,
        &DESTINATION_IPV6,
        TcpFields {
            source_port: TCP_TEST_SOURCE_PORT,
            destination_port: TCP_TEST_DESTINATION_PORT,
            sequence: 1_000,
            acknowledgement: 2_000,
            flags: 0x18,
            payload: b"hello",
            ..Default::default()
        },
    );
    let bad6 = tcp_segment(
        6,
        &SOURCE_IPV6,
        &DESTINATION_IPV6,
        TcpFields {
            source_port: TCP_TEST_SOURCE_PORT,
            destination_port: TCP_TEST_DESTINATION_PORT,
            sequence: 1_000,
            acknowledgement: 2_000,
            flags: 0x10,
            checksum: Some(0x1234),
            ..Default::default()
        },
    );
    let zero6 = tcp_segment(
        6,
        &SOURCE_IPV6,
        &DESTINATION_IPV6,
        TcpFields {
            source_port: TCP_TEST_SOURCE_PORT,
            destination_port: TCP_TEST_DESTINATION_PORT,
            sequence: 1_000,
            acknowledgement: 2_000,
            flags: 0x10,
            checksum: Some(0),
            ..Default::default()
        },
    );
    for segment in [
        &short_header,
        &long_header,
        &options_full,
        options_cut_two,
        options_cut_one,
        &bad,
        &zero,
    ] {
        frames.push(ethernet_frame(0x0800, &ipv4_transport(6, segment, None)?));
    }
    for segment in [&good6, &bad6, &zero6] {
        let plen = u16::try_from(segment.len())
            .map_err(|_| "IPv6 payload does not fit in 16 bits".to_string())?;
        frames.push(ethernet_frame(0x86dd, &ipv6_transport(6, segment, plen)));
    }
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

