/// Build one Ethernet/IPv4/UDP frame with optional trailing Ethernet padding.
fn udp_payload_frame(
    source_port: u16,
    destination_port: u16,
    payload: &[u8],
    padding: usize,
) -> Result<Vec<u8>, String> {
    let length = u16::try_from(
        8_usize
            .checked_add(payload.len())
            .ok_or_else(|| "payload length overflows".to_string())?,
    )
    .map_err(|_| "payload does not fit a UDP datagram".to_string())?;
    let segment = udp_segment(
        4,
        &SOURCE_ADDRESS,
        &DESTINATION_ADDRESS,
        UdpFields {
            source_port,
            destination_port,
            payload,
            length,
            ..Default::default()
        },
    );
    let datagram = ipv4_transport(17, &segment, None)?;
    let mut frame = ethernet_frame(0x0800, &datagram);
    frame.resize(frame.len().saturating_add(padding), 0);
    Ok(frame)
}

/// Build one Ethernet/IPv4/UDP frame with explicit addresses and ports.
fn udp_payload_frame_addressed(
    source: [u8; 4],
    destination: [u8; 4],
    source_port: u16,
    destination_port: u16,
    payload: &[u8],
) -> Result<Vec<u8>, String> {
    let length = u16::try_from(
        8_usize
            .checked_add(payload.len())
            .ok_or_else(|| "payload length overflows".to_string())?,
    )
    .map_err(|_| "payload does not fit a UDP datagram".to_string())?;
    let segment = udp_segment(
        4,
        &source,
        &destination,
        UdpFields {
            source_port,
            destination_port,
            payload,
            length,
            ..Default::default()
        },
    );
    let datagram = ipv4_packet_addressed(
        source,
        destination,
        Ipv4Fields {
            protocol: 17,
            identification: 0x1c46,
            flags: 0x4000,
            payload: &segment,
            ..Default::default()
        },
    )?;
    Ok(ethernet_frame(0x0800, &datagram))
}

