fn build_netflow_v9_adversarial() -> Result<Vec<u8>, String> {
    let mut frames = Vec::new();
    let huge_count = netflow_v9_message(
        65_535,
        1,
        NETFLOW_TIME,
        1,
        7,
        &[netflow_set(0, vec![1, 0, 0xff, 0xff, 0, 8, 0, 4])],
    );
    frames.push(udp_payload_frame(40_000, 2055, &huge_count, 0)?);

    let field: &[(u16, u16)] = &[(8, 4)];
    let mut templates = Vec::new();
    for index in 0..130_u16 {
        templates.push((1000 + index, field));
    }
    let flood = netflow_v9_message(
        2,
        1,
        NETFLOW_TIME,
        2,
        7,
        &[
            netflow_v9_template_set(&templates),
            netflow_data_set(1129, &[vec![10, 0, 0, 1]]),
        ],
    );
    frames.push(udp_payload_frame(40_000, 2055, &flood, 0)?);

    let wide: Vec<(u16, u16)> = std::iter::repeat_n((8_u16, 4_u16), 64).collect();
    let wide_record = vec![10_u8; 64 * 4];
    let wide_message = netflow_v9_message(
        2,
        1,
        NETFLOW_TIME,
        3,
        7,
        &[
            netflow_v9_template_set(&[(700, &wide)]),
            netflow_data_set(700, &[wide_record]),
        ],
    );
    frames.push(udp_payload_frame(40_000, 2055, &wide_message, 0)?);
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

fn build_ipfix() -> Result<Vec<u8>, String> {
    let standard: &[(u16, u16)] = &[(8, 4), (12, 4), (2, 8), (1, 8)];
    let scope: &[(u16, u16)] = &[(1, 4)];
    let options: &[(u16, u16)] = &[(8, 4), (1, 8)];
    let mut frames = Vec::new();

    let mut record = flow_pair([192, 0, 2, 5], [198, 51, 100, 6]);
    record.extend_from_slice(&10_u64.to_be_bytes());
    record.extend_from_slice(&1000_u64.to_be_bytes());
    let first = ipfix_message(
        NETFLOW_TIME,
        1,
        42,
        &[
            ipfix_template_set(&[(256, standard)]),
            netflow_data_set(256, &[record]),
        ],
    );
    frames.push(udp_payload_frame(40_000, 4739, &first, 0)?);

    let mut record = flow_pair([192, 0, 2, 7], [198, 51, 100, 8]);
    record.extend_from_slice(&11_u64.to_be_bytes());
    record.extend_from_slice(&2000_u64.to_be_bytes());
    let second = ipfix_message(NETFLOW_TIME + 1, 2, 42, &[netflow_data_set(256, &[record])]);
    frames.push(udp_payload_frame(40_000, 4739, &second, 0)?);

    let mut record = flow_pair([192, 0, 2, 9], [198, 51, 100, 10]);
    record.extend_from_slice(&12_u64.to_be_bytes());
    record.extend_from_slice(&3000_u64.to_be_bytes());
    let fourth = ipfix_message(NETFLOW_TIME + 3, 4, 42, &[netflow_data_set(256, &[record])]);
    frames.push(udp_payload_frame(40_000, 4739, &fourth, 0)?);

    let mut options_record = 42_u32.to_be_bytes().to_vec();
    options_record.extend_from_slice(&[192, 0, 2, 7]);
    options_record.extend_from_slice(&999_u64.to_be_bytes());
    let fifth = ipfix_message(
        NETFLOW_TIME + 4,
        5,
        42,
        &[
            ipfix_options_template_set(258, scope, options),
            netflow_data_set(258, &[options_record]),
        ],
    );
    frames.push(udp_payload_frame(40_000, 4739, &fifth, 0)?);

    let mut options_record = 43_u32.to_be_bytes().to_vec();
    options_record.extend_from_slice(&[192, 0, 2, 8]);
    options_record.extend_from_slice(&1000_u64.to_be_bytes());
    let sixth = ipfix_message(
        NETFLOW_TIME + 5,
        6,
        42,
        &[netflow_data_set(258, &[options_record])],
    );
    frames.push(udp_payload_frame(40_000, 4739, &sixth, 0)?);

    let mut record = flow_pair([192, 0, 2, 11], [198, 51, 100, 12]);
    record.extend_from_slice(&13_u64.to_be_bytes());
    record.extend_from_slice(&4000_u64.to_be_bytes());
    let seventh = ipfix_message(NETFLOW_TIME + 6, 7, 42, &[netflow_data_set(256, &[record])]);
    frames.push(udp_payload_frame(40_000, 4739, &seventh, 0)?);

    let missing = ipfix_message(
        NETFLOW_TIME + 7,
        8,
        42,
        &[netflow_data_set(300, &[vec![1, 2, 3, 4, 5, 6, 7, 8]])],
    );
    frames.push(udp_payload_frame(40_000, 4739, &missing, 0)?);

    let mut record = flow_pair([192, 0, 2, 13], [198, 51, 100, 14]);
    record.extend_from_slice(&14_u64.to_be_bytes());
    record.extend_from_slice(&5000_u64.to_be_bytes());
    let other_domain = ipfix_message(NETFLOW_TIME + 8, 9, 43, &[netflow_data_set(256, &[record])]);
    frames.push(udp_payload_frame(40_000, 4739, &other_domain, 0)?);

    let mut record = flow_pair([192, 0, 2, 15], [198, 51, 100, 16]);
    record.extend_from_slice(&15_u64.to_be_bytes());
    record.extend_from_slice(&6000_u64.to_be_bytes());
    let other_port = ipfix_message(
        NETFLOW_TIME + 9,
        10,
        42,
        &[netflow_data_set(256, &[record])],
    );
    frames.push(udp_payload_frame(40_001, 4739, &other_port, 0)?);

    let mut record = flow_pair([192, 0, 2, 17], [198, 51, 100, 18]);
    record.extend_from_slice(&16_u64.to_be_bytes());
    record.extend_from_slice(&7000_u64.to_be_bytes());
    let other_exporter = ipfix_message(
        NETFLOW_TIME + 10,
        11,
        42,
        &[netflow_data_set(256, &[record])],
    );
    frames.push(udp_payload_frame_addressed(
        [203, 0, 113, 9],
        [198, 51, 100, 2],
        40_000,
        4739,
        &other_exporter,
    )?);

    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

fn build_ipfix_withdrawal() -> Result<Vec<u8>, String> {
    let standard: &[(u16, u16)] = &[(8, 4), (12, 4)];
    let mut frames = Vec::new();
    let first = ipfix_message(
        NETFLOW_TIME,
        1,
        42,
        &[ipfix_template_set(&[(256, standard)])],
    );
    frames.push(udp_payload_frame(40_000, 4739, &first, 0)?);
    let second = ipfix_message(
        NETFLOW_TIME + 1,
        2,
        42,
        &[netflow_data_set(
            256,
            &[flow_pair([10, 0, 0, 1], [10, 0, 0, 2])],
        )],
    );
    frames.push(udp_payload_frame(40_000, 4739, &second, 0)?);
    let withdrawal = ipfix_message(
        NETFLOW_TIME + 2,
        3,
        42,
        &[ipfix_template_set(&[(256, &[])])],
    );
    frames.push(udp_payload_frame(40_000, 4739, &withdrawal, 0)?);
    let fourth = ipfix_message(
        NETFLOW_TIME + 3,
        4,
        42,
        &[netflow_data_set(
            256,
            &[flow_pair([10, 0, 0, 3], [10, 0, 0, 4])],
        )],
    );
    frames.push(udp_payload_frame(40_000, 4739, &fourth, 0)?);
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

fn build_netflow_v9_sequence() -> Result<Vec<u8>, String> {
    let standard: &[(u16, u16)] = &[(8, 4), (12, 4)];
    let mut frames = Vec::new();
    let template = netflow_v9_message(
        1,
        1000,
        NETFLOW_TIME,
        1,
        7,
        &[netflow_v9_template_set(&[(256, standard)])],
    );
    frames.push(udp_payload_frame(40_000, 2055, &template, 0)?);

    let record = flow_pair([10, 0, 0, 1], [10, 0, 0, 2]);
    for (index, sequence) in [(1_u32, 9_u32), (2, 10)] {
        let message = netflow_v9_message(
            1,
            1000,
            NETFLOW_TIME + index,
            sequence,
            7,
            &[netflow_data_set(256, std::slice::from_ref(&record))],
        );
        frames.push(udp_payload_frame(40_000, 2055, &message, 0)?);
    }

    let header = netflow_v9_header(1, 1000, NETFLOW_TIME + 3, 12, 7);
    frames.push(udp_payload_frame(40_000, 2055, &header, 0)?);
    frames.push(udp_payload_frame(
        40_000,
        2055,
        &netflow_v9_header(1, 1000, NETFLOW_TIME + 4, 14, 7),
        0,
    )?);
    let mut overrun = netflow_v9_header(1, 1000, NETFLOW_TIME + 5, 16, 7);
    overrun.extend_from_slice(&[0, 0, 0, 16, 0, 1, 0, 2]);
    frames.push(udp_payload_frame(40_000, 2055, &overrun, 0)?);

    let missing = netflow_v9_message(
        1,
        1000,
        NETFLOW_TIME + 6,
        18,
        7,
        &[netflow_data_set(300, &[vec![1, 2, 3, 4, 5, 6, 7, 8]])],
    );
    frames.push(udp_payload_frame(40_000, 2055, &missing, 0)?);
    let accepted = netflow_v9_message(
        1,
        1000,
        NETFLOW_TIME + 7,
        19,
        7,
        &[netflow_data_set(256, std::slice::from_ref(&record))],
    );
    frames.push(udp_payload_frame(40_000, 2055, &accepted, 0)?);

    let mut incomplete = netflow_v9_header(1, 1000, NETFLOW_TIME + 8, 21, 7);
    incomplete.extend_from_slice(&netflow_set(0, vec![1, 0, 0, 2, 0, 8, 0, 4]));
    frames.push(udp_payload_frame(40_000, 2055, &incomplete, 0)?);

    let skipped = netflow_v9_message(
        1,
        1000,
        NETFLOW_TIME + 9,
        20,
        7,
        &[netflow_data_set(256, std::slice::from_ref(&record))],
    );
    frames.push(udp_payload_frame(40_000, 2055, &skipped, 0)?);

    let wide: Vec<(u16, u16)> = std::iter::repeat_n((8_u16, 4_u16), 61).collect();
    let rejected = netflow_v9_message(
        1,
        1000,
        NETFLOW_TIME + 10,
        25,
        7,
        &[netflow_v9_template_set(&[(257, &wide)])],
    );
    frames.push(udp_payload_frame(40_000, 2055, &rejected, 0)?);
    let missing_wide = netflow_v9_message(
        1,
        1000,
        NETFLOW_TIME + 11,
        26,
        7,
        &[netflow_data_set(257, &[vec![1, 2, 3, 4]])],
    );
    frames.push(udp_payload_frame(40_000, 2055, &missing_wide, 0)?);
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

fn build_ipfix_sequence() -> Result<Vec<u8>, String> {
    let standard: &[(u16, u16)] = &[(8, 4)];
    let mut frames = Vec::new();
    let template = ipfix_message(
        NETFLOW_TIME,
        1,
        42,
        &[ipfix_template_set(&[(256, standard)])],
    );
    frames.push(udp_payload_frame(40_000, 4739, &template, 0)?);

    let record = vec![10, 0, 0, 1];
    let first_data = ipfix_message(
        NETFLOW_TIME + 1,
        9,
        42,
        &[netflow_data_set(256, std::slice::from_ref(&record))],
    );
    frames.push(udp_payload_frame(40_000, 4739, &first_data, 0)?);
    frames.push(udp_payload_frame(
        40_000,
        4739,
        &ipfix_header(16, NETFLOW_TIME + 2, 10, 42),
        0,
    )?);
    frames.push(udp_payload_frame(
        40_000,
        4739,
        &ipfix_message(NETFLOW_TIME + 3, 11, 42, &[vec![0, 2, 0, 3]]),
        0,
    )?);
    frames.push(udp_payload_frame(
        40_000,
        4739,
        &ipfix_message(NETFLOW_TIME + 4, 12, 42, &[vec![0, 2, 0, 40, 0, 1, 0, 2]]),
        0,
    )?);
    let missing = ipfix_message(
        NETFLOW_TIME + 5,
        13,
        42,
        &[netflow_data_set(300, &[vec![1, 2, 3, 4]])],
    );
    frames.push(udp_payload_frame(40_000, 4739, &missing, 0)?);
    let accepted = ipfix_message(
        NETFLOW_TIME + 6,
        13,
        42,
        &[netflow_data_set(256, std::slice::from_ref(&record))],
    );
    frames.push(udp_payload_frame(40_000, 4739, &accepted, 0)?);

    let mut incomplete = ipfix_header(12, NETFLOW_TIME + 7, 20, 42);
    incomplete.extend_from_slice(&netflow_set(2, vec![1, 0, 0, 2, 0, 8, 0, 4]));
    frames.push(udp_payload_frame(40_000, 4739, &incomplete, 0)?);
    let skipped = ipfix_message(
        NETFLOW_TIME + 8,
        14,
        42,
        &[netflow_data_set(256, std::slice::from_ref(&record))],
    );
    frames.push(udp_payload_frame(40_000, 4739, &skipped, 0)?);

    let wide: Vec<(u16, u16)> = std::iter::repeat_n((8_u16, 4_u16), 61).collect();
    let rejected = ipfix_message(
        NETFLOW_TIME + 9,
        30,
        42,
        &[ipfix_template_set(&[(257, &wide)])],
    );
    frames.push(udp_payload_frame(40_000, 4739, &rejected, 0)?);
    let missing_wide = ipfix_message(
        NETFLOW_TIME + 10,
        30,
        42,
        &[netflow_data_set(257, &[vec![1, 2, 3, 4]])],
    );
    frames.push(udp_payload_frame(40_000, 4739, &missing_wide, 0)?);
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

fn build_ipfix_malformed() -> Result<Vec<u8>, String> {
    let standard: &[(u16, u16)] = &[(8, 4), (12, 4)];
    let template = ipfix_template_set(&[(256, standard)]);
    let mut frames = Vec::new();
    let short = ipfix_message_declared(1, NETFLOW_TIME, 1, 42, std::slice::from_ref(&template));
    frames.push(udp_payload_frame(40_000, 4739, &short, 0)?);
    let long = ipfix_message_declared(500, NETFLOW_TIME, 2, 42, &[template]);
    frames.push(udp_payload_frame(40_000, 4739, &long, 0)?);
    let zero = ipfix_message_declared(
        0,
        NETFLOW_TIME,
        3,
        42,
        &[netflow_data_set(256, &[vec![1, 2, 3, 4]])],
    );
    frames.push(udp_payload_frame(40_000, 4739, &zero, 0)?);
    let short_set = ipfix_message(NETFLOW_TIME, 4, 42, &[vec![0, 2, 0, 3]]);
    frames.push(udp_payload_frame(40_000, 4739, &short_set, 0)?);
    let overrun = ipfix_message(NETFLOW_TIME, 5, 42, &[vec![0, 2, 0, 40, 0, 1, 0, 2]]);
    frames.push(udp_payload_frame(40_000, 4739, &overrun, 0)?);
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

fn build_ipfix_adversarial() -> Result<Vec<u8>, String> {
    let mut frames = Vec::new();
    let huge_length = ipfix_message_declared(
        65_535,
        NETFLOW_TIME,
        1,
        42,
        &[ipfix_template_set(&[(256, &[(8, 4)])])],
    );
    frames.push(udp_payload_frame(40_000, 4739, &huge_length, 0)?);
    let huge_count = ipfix_message(
        NETFLOW_TIME,
        2,
        42,
        &[netflow_set(2, vec![1, 0, 0xff, 0xff, 0, 8, 0, 4])],
    );
    frames.push(udp_payload_frame(40_000, 4739, &huge_count, 0)?);
    let huge_options = ipfix_message(
        NETFLOW_TIME,
        3,
        42,
        &[netflow_set(
            3,
            vec![1, 2, 0xff, 0xff, 0xff, 0xff, 0, 8, 0, 4],
        )],
    );
    frames.push(udp_payload_frame(40_000, 4739, &huge_options, 0)?);

    let field: &[(u16, u16)] = &[(8, 4)];
    let mut templates = Vec::new();
    for index in 0..130_u16 {
        templates.push((1000 + index, field));
    }
    let flood = ipfix_message(NETFLOW_TIME, 4, 42, &[ipfix_template_set(&templates)]);
    frames.push(udp_payload_frame(40_000, 4739, &flood, 0)?);
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}
