const T20_CLIENT: [u8; 4] = [192, 0, 2, 1];

const T20_SERVER: [u8; 4] = [192, 0, 2, 2];

/// Build one Ethernet/IPv4/TCP frame between explicit addresses.
fn tcp_payload_between(
    source: [u8; 4],
    destination: [u8; 4],
    source_port: u16,
    destination_port: u16,
    sequence: u32,
    acknowledgement: u32,
    payload: &[u8],
) -> Result<Vec<u8>, String> {
    let segment = tcp_segment(
        4,
        &source,
        &destination,
        TcpFields {
            source_port,
            destination_port,
            sequence,
            acknowledgement,
            flags: 0x18,
            payload,
            ..Default::default()
        },
    );
    let datagram = ipv4_transport_between(source, destination, 6, &segment)?;
    Ok(ethernet_frame(0x0800, &datagram))
}

/// Build a TCP frame with FIN set and an optional payload.
fn tcp_fin_between(
    source: [u8; 4],
    destination: [u8; 4],
    source_port: u16,
    destination_port: u16,
    sequence: u32,
    acknowledgement: u32,
    payload: &[u8],
) -> Result<Vec<u8>, String> {
    let segment = tcp_segment(
        4,
        &source,
        &destination,
        TcpFields {
            source_port,
            destination_port,
            sequence,
            acknowledgement,
            flags: 0x19,
            payload,
            ..Default::default()
        },
    );
    let datagram = ipv4_transport_between(source, destination, 6, &segment)?;
    Ok(ethernet_frame(0x0800, &datagram))
}

/// One empty TCP segment carrying FIN and ACK.
fn tcp_fin_empty_between(
    source: [u8; 4],
    destination: [u8; 4],
    source_port: u16,
    destination_port: u16,
    sequence: u32,
    acknowledgement: u32,
) -> Result<Vec<u8>, String> {
    let segment = tcp_segment(
        4,
        &source,
        &destination,
        TcpFields {
            source_port,
            destination_port,
            sequence,
            acknowledgement,
            flags: 0x11,
            ..Default::default()
        },
    );
    let datagram = ipv4_transport_between(source, destination, 6, &segment)?;
    Ok(ethernet_frame(0x0800, &datagram))
}

/// Prefix a DNS message with its two-octet TCP length, or a declared length.
fn dns_tcp_message(message: &[u8], declared: Option<u16>) -> Vec<u8> {
    let length = declared.unwrap_or_else(|| u16::try_from(message.len()).unwrap_or(u16::MAX));
    let mut payload = length.to_be_bytes().to_vec();
    payload.extend_from_slice(message);
    payload
}

fn build_dns_tcp() -> Result<Vec<u8>, String> {
    let mut query = dns_header(0x1234, 0x0100, [1, 0, 0, 0]);
    query.extend_from_slice(&dns_question("example.com", 1, 1));
    let mut response = dns_header(0x1234, 0x8180, [1, 1, 0, 0]);
    response.extend_from_slice(&dns_question("example.com", 1, 1));
    response.extend_from_slice(&dns_record(&[0xc0, 0x0c], 1, 1, 300, &[93, 184, 216, 34]));
    let mut second_query = dns_header(0x1235, 0x0100, [1, 0, 0, 0]);
    second_query.extend_from_slice(&dns_question("b.example", 1, 1));
    let mut second_response = dns_header(0x1235, 0x8180, [1, 1, 0, 0]);
    second_response.extend_from_slice(&dns_question("b.example", 1, 1));
    second_response.extend_from_slice(&dns_record(&[0xc0, 0x0c], 1, 1, 60, &[1, 2, 3, 4]));

    let mut client_sequence = 1000_u32;
    let mut server_sequence = 5000_u32;
    let mut frames = Vec::new();
    let mut push_client = |payload: &[u8], frames: &mut Vec<Vec<u8>>| -> Result<(), String> {
        frames.push(tcp_payload_between(
            T20_CLIENT,
            T20_SERVER,
            40_000,
            53,
            client_sequence,
            1,
            payload,
        )?);
        client_sequence =
            client_sequence.saturating_add(u32::try_from(payload.len()).unwrap_or(u32::MAX));
        Ok(())
    };
    let mut push_server = |payload: &[u8], frames: &mut Vec<Vec<u8>>| -> Result<(), String> {
        frames.push(tcp_payload_between(
            T20_SERVER,
            T20_CLIENT,
            53,
            40_000,
            server_sequence,
            1,
            payload,
        )?);
        server_sequence =
            server_sequence.saturating_add(u32::try_from(payload.len()).unwrap_or(u32::MAX));
        Ok(())
    };

    let first_query = dns_tcp_message(&query, None);
    push_client(&first_query, &mut frames)?;
    // A repeated query inside the retransmission window keeps the original
    // request frame and time.
    push_client(&first_query, &mut frames)?;
    push_server(&dns_tcp_message(&response, None), &mut frames)?;
    let mut two_messages = dns_tcp_message(&second_query, None);
    two_messages.extend_from_slice(&dns_tcp_message(first_query.get(2..).unwrap_or(&[]), None));
    push_client(&two_messages, &mut frames)?;
    push_server(&dns_tcp_message(&second_response, None), &mut frames)?;
    let mut third_query = dns_header(0x1236, 0x0100, [1, 0, 0, 0]);
    third_query.extend_from_slice(&dns_question("c.example", 1, 1));
    let mut mixed = dns_tcp_message(&second_query, None);
    mixed.extend_from_slice(&dns_tcp_message(&[0x00, 0x02, 0x01, 0x02], None));
    mixed.extend_from_slice(&dns_tcp_message(&third_query, None));
    push_client(&mixed, &mut frames)?;
    push_client(&[0x00, 0x00], &mut frames)?;
    push_client(&[0x00], &mut frames)?;
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

/// Encode a TLS hello extension.
fn tls_extension(kind: u16, body: &[u8]) -> Vec<u8> {
    let mut out = kind.to_be_bytes().to_vec();
    out.extend_from_slice(&u16::try_from(body.len()).unwrap_or(u16::MAX).to_be_bytes());
    out.extend_from_slice(body);
    out
}

fn tls_vector(body: &[u8]) -> Vec<u8> {
    let mut out = u16::try_from(body.len())
        .unwrap_or(u16::MAX)
        .to_be_bytes()
        .to_vec();
    out.extend_from_slice(body);
    out
}

fn tls_handshake(message_type: u8, body: &[u8]) -> Vec<u8> {
    let mut out = vec![message_type];
    let length = u32::try_from(body.len()).unwrap_or(u32::MAX);
    out.extend_from_slice(length.to_be_bytes().get(1..).unwrap_or(&[]));
    out.extend_from_slice(body);
    out
}

fn tls_server_hello() -> Vec<u8> {
    let mut body = 0x0303_u16.to_be_bytes().to_vec();
    body.extend_from_slice(&[0x33; 32]);
    body.push(32);
    body.extend_from_slice(&[0x22; 32]);
    body.extend_from_slice(&0x1301_u16.to_be_bytes());
    body.push(0);
    let mut key_exchange = 0x001d_u16.to_be_bytes().to_vec();
    key_exchange.extend_from_slice(&32_u16.to_be_bytes());
    key_exchange.extend_from_slice(&[0x44; 32]);
    let mut extensions = Vec::new();
    extensions.extend_from_slice(&tls_extension(43, &[0x03, 0x04]));
    extensions.extend_from_slice(&tls_extension(51, &key_exchange));
    body.extend_from_slice(
        &u16::try_from(extensions.len())
            .unwrap_or(u16::MAX)
            .to_be_bytes(),
    );
    body.extend_from_slice(&extensions);
    tls_handshake(2, &body)
}

fn build_tls_handshake() -> Result<Vec<u8>, String> {
    let hello = tls_record_pdu(22, 0x0301, &tls20_client_hello());
    let server = tls_record_pdu(22, 0x0303, &tls_server_hello());
    let alerts = tls_record_pdu(21, 0x0303, &[0x02, 40]);
    let mut two_alerts = alerts.clone();
    two_alerts.extend_from_slice(&tls_record_pdu(21, 0x0303, &[0x01, 0x00]));
    let empty_handshake = tls_record_pdu(22, 0x0303, &[]);
    let fragment = tls_record_pdu(22, 0x0303, &[0x01, 0x00, 0x00, 0x05, 0x03]);
    let application = tls_record_pdu(23, 0x0303, b"application data");
    let partial_header = vec![0x16, 0x03, 0x03, 0x00];

    let mut client_sequence = 1000_u32;
    let mut server_sequence = 5000_u32;
    let mut frames = Vec::new();
    let mut push_client = |payload: &[u8], frames: &mut Vec<Vec<u8>>| -> Result<(), String> {
        frames.push(tcp_payload_between(
            T20_CLIENT,
            T20_SERVER,
            40_000,
            443,
            client_sequence,
            1,
            payload,
        )?);
        client_sequence =
            client_sequence.saturating_add(u32::try_from(payload.len()).unwrap_or(u32::MAX));
        Ok(())
    };
    let mut push_server = |payload: &[u8], frames: &mut Vec<Vec<u8>>| -> Result<(), String> {
        frames.push(tcp_payload_between(
            T20_SERVER,
            T20_CLIENT,
            443,
            40_000,
            server_sequence,
            1,
            payload,
        )?);
        server_sequence =
            server_sequence.saturating_add(u32::try_from(payload.len()).unwrap_or(u32::MAX));
        Ok(())
    };
    push_client(&hello, &mut frames)?;
    push_server(&server, &mut frames)?;
    push_server(&two_alerts, &mut frames)?;
    push_client(&empty_handshake, &mut frames)?;
    push_client(&fragment, &mut frames)?;
    push_client(&application, &mut frames)?;
    push_client(&partial_header, &mut frames)?;
    // Cleartext on a TLS port must stay TCP; a fresh conversation keeps the
    // preceding partial record from claiming it during reassembly.
    frames.push(tcp_payload_between(
        T20_CLIENT,
        T20_SERVER,
        40_001,
        443,
        1000,
        1,
        b"hello world",
    )?);
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

fn tls_exchange(port: u16, payloads: &[(bool, Vec<u8>)]) -> Result<Vec<u8>, String> {
    tls_exchange_from(port, 40_000, payloads)
}

fn tls_exchange_from(
    port: u16,
    client_port: u16,
    payloads: &[(bool, Vec<u8>)],
) -> Result<Vec<u8>, String> {
    let frames = tls_frames_from(port, client_port, payloads)?;
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

fn http_objects_push(
    source: [u8; 4],
    destination: [u8; 4],
    source_port: u16,
    destination_port: u16,
    sequence: &mut u32,
    payload: &[u8],
    frames: &mut Vec<Vec<u8>>,
) -> Result<(), String> {
    frames.push(tcp_payload_between(
        source,
        destination,
        source_port,
        destination_port,
        *sequence,
        1,
        payload,
    )?);
    *sequence = sequence.saturating_add(u32::try_from(payload.len()).unwrap_or(u32::MAX));
    Ok(())
}

fn http_objects_exchange(
    uri: &str,
    response: &[u8],
    client_sequence: &mut u32,
    server_sequence: &mut u32,
    frames: &mut Vec<Vec<u8>>,
) -> Result<(), String> {
    let request = format!("GET {uri} HTTP/1.1\r\nHost: h\r\n\r\n");
    http_objects_push(
        T20_CLIENT,
        T20_SERVER,
        40_000,
        80,
        client_sequence,
        request.as_bytes(),
        frames,
    )?;
    http_objects_push(
        T20_SERVER,
        T20_CLIENT,
        80,
        40_000,
        server_sequence,
        response,
        frames,
    )
}

fn http_plain_response(body: &[u8]) -> Vec<u8> {
    let mut response = format!(
        "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: {}\r\n\r\n",
        body.len()
    )
    .into_bytes();
    response.extend_from_slice(body);
    response
}

fn build_http_objects() -> Result<Vec<u8>, String> {
    let mut frames = Vec::new();
    let mut client_sequence = 10_000_u32;
    let mut server_sequence = 50_000_u32;
    let plain = |body: &[u8]| http_plain_response(body);

    http_objects_exchange(
        "/normal.txt",
        &plain(b"Hello, world!"),
        &mut client_sequence,
        &mut server_sequence,
        &mut frames,
    )?;
    http_objects_exchange(
        "/chunked.txt",
        b"HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\nContent-Type: text/plain\r\n\r\n5\r\nabcde\r\n6\r\nfghijk\r\n0\r\n\r\n",
        &mut client_sequence,
        &mut server_sequence,
        &mut frames,
    )?;
    http_objects_push(
        T20_CLIENT,
        T20_SERVER,
        40_000,
        80,
        &mut client_sequence,
        b"POST /post-target HTTP/1.1\r\nHost: h\r\nContent-Length: 4\r\n\r\ndata",
        &mut frames,
    )?;
    http_objects_push(
        T20_SERVER,
        T20_CLIENT,
        80,
        40_000,
        &mut server_sequence,
        b"HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Length: 7\r\n\r\nresp000",
        &mut frames,
    )?;
    http_objects_exchange(
        "/zero.bin",
        b"HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Length: 0\r\n\r\n",
        &mut client_sequence,
        &mut server_sequence,
        &mut frames,
    )?;
    http_objects_exchange(
        "/gz.txt",
        b"HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Encoding: gzip\r\nContent-Length: 23\r\n\r\n\x1f\x8b\x08\x00\x00\x00\x00\x00\x00\xff\x4b\x4c\x4a\x06\x00\xc2\x41\x24\x35\x03\x00\x00\x00",
        &mut client_sequence,
        &mut server_sequence,
        &mut frames,
    )?;
    http_objects_exchange(
        "/cd.txt",
        b"HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Disposition: attachment; filename=\"other.txt\"\r\nContent-Length: 5\r\n\r\nhello",
        &mut client_sequence,
        &mut server_sequence,
        &mut frames,
    )?;
    http_objects_push(
        T20_SERVER,
        T20_CLIENT,
        80,
        40_000,
        &mut server_sequence,
        b"HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=UTF-8\r\nContent-Length: 5\r\n\r\nhello",
        &mut frames,
    )?;
    http_objects_push(
        T20_SERVER,
        T20_CLIENT,
        80,
        40_000,
        &mut server_sequence,
        b"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nhello",
        &mut frames,
    )?;
    http_objects_push(
        T20_SERVER,
        T20_CLIENT,
        80,
        40_000,
        &mut server_sequence,
        b"HTTP/1.1 200 OK\r\nContent-Type: \r\nContent-Length: 5\r\n\r\nhello",
        &mut frames,
    )?;
    for uri in [
        "/x?q=1#frag",
        "/raw\\back\\slash.txt",
        "/CON",
        "/file.",
        "/dir/",
        "/",
        "http://other.test/abs.txt",
        "//double//slash//name.txt",
    ] {
        http_objects_exchange(
            uri,
            &plain(b"hello"),
            &mut client_sequence,
            &mut server_sequence,
            &mut frames,
        )?;
    }
    for uri in [
        format!("/{}.txt", "L".repeat(400)),
        format!("/{}.tar.gz", "e".repeat(300)),
    ] {
        http_objects_exchange(
            &uri,
            &plain(b"hello"),
            &mut client_sequence,
            &mut server_sequence,
            &mut frames,
        )?;
    }
    for body in [b"one".as_slice(), b"two".as_slice(), b"three".as_slice()] {
        http_objects_exchange(
            "/dup.txt",
            &plain(body),
            &mut client_sequence,
            &mut server_sequence,
            &mut frames,
        )?;
    }
    http_objects_exchange(
        "/empty-chunked.txt",
        b"HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n0\r\n\r\n",
        &mut client_sequence,
        &mut server_sequence,
        &mut frames,
    )?;
    http_objects_exchange(
        "/a",
        &plain(b"a"),
        &mut client_sequence,
        &mut server_sequence,
        &mut frames,
    )?;
    http_objects_push(
        T20_SERVER,
        T20_CLIENT,
        80,
        40_000,
        &mut server_sequence,
        b"HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: 1\r\n\r\nb",
        &mut frames,
    )?;
    http_objects_push(
        T20_CLIENT,
        T20_SERVER,
        40_000,
        80,
        &mut client_sequence,
        b"GET /malformed HTTP/1.1\r\nHost x\r\n\r\n",
        &mut frames,
    )?;
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

fn build_http_object_names() -> Result<Vec<u8>, String> {
    let mut frames = Vec::new();
    let mut client_sequence = 20_000_u32;
    let mut server_sequence = 60_000_u32;
    let mut push_client = |payload: &[u8], frames: &mut Vec<Vec<u8>>| -> Result<(), String> {
        frames.push(tcp_payload_between(
            T20_CLIENT,
            T20_SERVER,
            40_001,
            80,
            client_sequence,
            1,
            payload,
        )?);
        client_sequence =
            client_sequence.saturating_add(u32::try_from(payload.len()).unwrap_or(u32::MAX));
        Ok(())
    };
    let mut push_server = |payload: &[u8], frames: &mut Vec<Vec<u8>>| -> Result<(), String> {
        frames.push(tcp_payload_between(
            T20_SERVER,
            T20_CLIENT,
            80,
            40_001,
            server_sequence,
            1,
            payload,
        )?);
        server_sequence =
            server_sequence.saturating_add(u32::try_from(payload.len()).unwrap_or(u32::MAX));
        Ok(())
    };
    let plain = b"HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: 1\r\n\r\nx";
    for uri in [
        "/.",
        "/..",
        "/caf\u{e9}.txt",
        "/../../etc/passwd",
        "/a/..%2f..%2fetc",
        "/%00",
        "/..%2f..%2fetc",
        "/%2e%2e",
    ] {
        let request = format!("GET {uri} HTTP/1.1\r\nHost: h\r\n\r\n");
        push_client(request.as_bytes(), &mut frames)?;
        push_server(plain, &mut frames)?;
    }
    push_server(
        b"HTTP/1.1 200 OK\r\nContent-Type: a\x7fb/c\r\nContent-Length: 1\r\n\r\nx",
        &mut frames,
    )?;
    push_server(
        "HTTP/1.1 200 OK\r\nContent-Type: caf\u{e9}.txt\r\nContent-Length: 1\r\n\r\nx".as_bytes(),
        &mut frames,
    )?;
    for (request, response) in [
        (
            b"GET /truncated.bin HTTP/1.1\r\nHost: h\r\n\r\n".as_slice(),
            b"HTTP/1.1 200 OK\r\nContent-Length: 100\r\n\r\n0123456789".as_slice(),
        ),
        (
            b"GET /zero.bin HTTP/1.1\r\nHost: h\r\n\r\n".as_slice(),
            b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n".as_slice(),
        ),
        (
            b"GET /chunk-partial HTTP/1.1\r\nHost: h\r\n\r\n".as_slice(),
            b"HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n5\r\nab".as_slice(),
        ),
        (
            b"GET /close.txt HTTP/1.1\r\nHost: h\r\n\r\n".as_slice(),
            b"HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\n\r\nclose-body".as_slice(),
        ),
    ] {
        push_client(request, &mut frames)?;
        push_server(response, &mut frames)?;
    }
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

/// One midstream HTTP conversation for the split-object fixture.
struct ObjectConnection<'a> {
    frames: &'a mut Vec<Vec<u8>>,
    client_port: u16,
    client_sequence: u32,
    server_sequence: u32,
}

impl<'a> ObjectConnection<'a> {
    fn new(frames: &'a mut Vec<Vec<u8>>, client_port: u16) -> Self {
        Self {
            frames,
            client_port,
            client_sequence: 1000,
            server_sequence: 5000,
        }
    }

    fn client(&mut self, payload: &[u8]) -> Result<(), String> {
        self.frames.push(tcp_payload_between(
            T20_CLIENT,
            T20_SERVER,
            self.client_port,
            80,
            self.client_sequence,
            self.server_sequence,
            payload,
        )?);
        self.client_sequence = self
            .client_sequence
            .saturating_add(u32::try_from(payload.len()).unwrap_or(u32::MAX));
        Ok(())
    }

    fn server(&mut self, payload: &[u8]) -> Result<(), String> {
        self.frames.push(tcp_payload_between(
            T20_SERVER,
            T20_CLIENT,
            80,
            self.client_port,
            self.server_sequence,
            self.client_sequence,
            payload,
        )?);
        self.server_sequence = self
            .server_sequence
            .saturating_add(u32::try_from(payload.len()).unwrap_or(u32::MAX));
        Ok(())
    }

    /// Repeat bytes at an already-used server sequence (a conflicting overlap).
    fn server_at(&mut self, sequence: u32, payload: &[u8]) -> Result<(), String> {
        self.frames.push(tcp_payload_between(
            T20_SERVER,
            T20_CLIENT,
            80,
            self.client_port,
            sequence,
            self.client_sequence,
            payload,
        )?);
        Ok(())
    }

    fn server_fin(&mut self, payload: &[u8]) -> Result<(), String> {
        self.frames.push(tcp_fin_between(
            T20_SERVER,
            T20_CLIENT,
            80,
            self.client_port,
            self.server_sequence,
            self.client_sequence,
            payload,
        )?);
        self.server_sequence = self
            .server_sequence
            .saturating_add(u32::try_from(payload.len()).unwrap_or(u32::MAX))
            .saturating_add(1);
        Ok(())
    }

    fn server_fin_at(&mut self, sequence: u32, payload: &[u8]) -> Result<(), String> {
        self.frames.push(tcp_fin_between(
            T20_SERVER,
            T20_CLIENT,
            80,
            self.client_port,
            sequence,
            self.client_sequence,
            payload,
        )?);
        Ok(())
    }
}

/// Build multi-segment HTTP object exports.
fn build_http_objects_split() -> Result<Vec<u8>, String> {
    let mut frames = Vec::new();

    // A Content-Length body across three segments.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_500);
        connection.client(b"GET /split-cl HTTP/1.1\r\nHost: h\r\n\r\n")?;
        let response =
            b"HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: 11\r\n\r\nhello world";
        connection.server(response.get(..50).unwrap_or(&[]))?;
        connection.server(response.get(50..70).unwrap_or(&[]))?;
        connection.server(response.get(70..).unwrap_or(&[]))?;
        connection.server_fin(b"")?;
    }

    // A chunked body split inside the chunk data.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_501);
        connection.client(b"GET /split-chunked HTTP/1.1\r\nHost: h\r\n\r\n")?;
        let response = b"HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\nContent-Type: text/plain\r\n\r\n5\r\nhello\r\n6\r\n world\r\n0\r\n\r\n";
        let cut = response
            .windows(5)
            .position(|window| window == b"world")
            .map(|index| index + 3)
            .unwrap_or(response.len() / 2);
        connection.server(response.get(..cut).unwrap_or(&[]))?;
        connection.server(response.get(cut..).unwrap_or(&[]))?;
        connection.server_fin(b"")?;
    }

    // A close-delimited response: header, part of the body, then FIN+body.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_502);
        connection.client(b"GET /close-fin HTTP/1.1\r\nHost: h\r\n\r\n")?;
        connection.server(b"HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\n\r\n")?;
        connection.server(b"close-")?;
        connection.server_fin(b"body")?;
    }

    // Two objects whose bodies each span a segment boundary.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_503);
        connection.client(b"GET /one HTTP/1.1\r\nHost: h\r\n\r\n")?;
        let first = b"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nfirst";
        connection.server(first.get(..40).unwrap_or(&[]))?;
        connection.server(first.get(40..).unwrap_or(&[]))?;
        connection.client(b"GET /two HTTP/1.1\r\nHost: h\r\n\r\n")?;
        let second = b"HTTP/1.1 200 OK\r\nContent-Length: 6\r\n\r\nsecond";
        connection.server(second.get(..40).unwrap_or(&[]))?;
        connection.server(second.get(40..).unwrap_or(&[]))?;
        connection.server_fin(b"")?;
    }

    // A truncated Content-Length body never completes.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_504);
        connection.client(b"GET /truncated-cl HTTP/1.1\r\nHost: h\r\n\r\n")?;
        connection.server(b"HTTP/1.1 200 OK\r\nContent-Length: 100\r\n\r\n0123456789")?;
        connection.server_fin(b"")?;
    }

    // A truncated chunked body never completes.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_505);
        connection.client(b"GET /truncated-chunk HTTP/1.1\r\nHost: h\r\n\r\n")?;
        connection.server(b"HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n5\r\nab")?;
        connection.server_fin(b"")?;
    }

    // A gap that never fills: the body is incomplete and no object appears.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_506);
        connection.client(b"GET /gap HTTP/1.1\r\nHost: h\r\n\r\n")?;
        let header = b"HTTP/1.1 200 OK\r\nContent-Length: 20\r\n\r\n";
        let mut start = header.to_vec();
        start.extend_from_slice(b"ABCDE");
        connection.server(&start)?;
        let gap_start = connection.server_sequence.saturating_add(10);
        connection.server_at(gap_start, b"PQRST")?;
        connection.server_fin(b"")?;
    }

    // A conflicting retransmission keeps the first-arrived body bytes.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_507);
        connection.client(b"GET /overlap HTTP/1.1\r\nHost: h\r\n\r\n")?;
        let header = b"HTTP/1.1 200 OK\r\nContent-Length: 10\r\n\r\n";
        let mut first = header.to_vec();
        first.extend_from_slice(b"ABCDE");
        connection.server(&first)?;
        let retransmit = connection.server_sequence.saturating_sub(3);
        connection.server_at(retransmit, b"xyz")?;
        connection.server(b"FGHIJ")?;
        connection.server_fin(b"")?;
    }

    // A complete response followed by unparseable bytes in the same frame:
    // the remainder exports as a continuation named from the request.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_508);
        connection.client(b"GET /continue HTTP/1.1\r\nHost: h\r\n\r\n")?;
        connection
            .server(b"HTTP/1.1 200 OK\r\nContent-Length: 3\r\n\r\nabc1.1 200 OK\r\nContent-Len")?;
        connection.server_fin(b"")?;
    }

    // A continuation in its own frame has no association: object<frame>.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_509);
        connection.client(b"GET /tail HTTP/1.1\r\nHost: h\r\n\r\n")?;
        connection.server(b"HTTP/1.1 200 OK\r\nContent-Length: 3\r\n\r\nabc")?;
        connection.server(b"garbage\n")?;
        connection.server_fin(b"")?;
    }

    // Extra bytes in a HEAD response's frame are its body for export.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_510);
        connection.client(b"HEAD /head-extra HTTP/1.1\r\nHost: h\r\n\r\n")?;
        connection.server(b"HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\n\r\njunk\n")?;
        connection.server_fin(b"")?;
    }

    // A close-delimited response carried entirely by the FIN segment.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_511);
        connection.client(b"GET /all-fin HTTP/1.1\r\nHost: h\r\n\r\n")?;
        connection.server_fin(b"HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\n\r\nclose-body")?;
    }

    // An empty close-delimited body produces no object.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_512);
        connection.client(b"GET /empty-close HTTP/1.1\r\nHost: h\r\n\r\n")?;
        connection.server(b"HTTP/1.1 200 OK\r\n\r\n")?;
        connection.server_fin(b"")?;
    }

    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

/// Build FIN, gap and continuation boundary cases for object export.
fn build_http_objects_fin_edge() -> Result<Vec<u8>, String> {
    let mut frames = Vec::new();
    let close_header = b"HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\n\r\n";
    let close_body = b"close-body";

    // Header and part of the body, a body gap, then an empty FIN.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_520);
        connection.client(b"GET /close-gap HTTP/1.1\r\nHost: h\r\n\r\n")?;
        let mut first = close_header.to_vec();
        first.extend_from_slice(b"close-");
        connection.server(&first)?;
        let rest = 5000_u32
            .saturating_add(u32::try_from(close_header.len()).unwrap_or(0))
            .saturating_add(8);
        connection.server_at(rest, b"body")?;
        let fin = 5000_u32
            .saturating_add(u32::try_from(close_header.len()).unwrap_or(0))
            .saturating_add(u32::try_from(close_body.len()).unwrap_or(0));
        connection.server_fin_at(fin, b"")?;
    }

    // Header and five bytes, then a FIN after the uncaptured tail.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_521);
        connection.client(b"GET /gap-fin-end HTTP/1.1\r\nHost: h\r\n\r\n")?;
        let header = b"HTTP/1.1 200 OK\r\n\r\n";
        let mut first = header.to_vec();
        first.extend_from_slice(b"abcde");
        connection.server(&first)?;
        let fin = 5000_u32
            .saturating_add(u32::try_from(header.len()).unwrap_or(0))
            .saturating_add(10);
        connection.server_fin_at(fin, b"")?;
    }

    // A gap whose remaining body bytes arrive in the FIN segment.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_522);
        connection.client(b"GET /gap-fin-body HTTP/1.1\r\nHost: h\r\n\r\n")?;
        let mut first = close_header.to_vec();
        first.extend_from_slice(b"close-");
        connection.server(&first)?;
        let fin = 5000_u32
            .saturating_add(u32::try_from(close_header.len()).unwrap_or(0))
            .saturating_add(8);
        connection.server_fin_at(fin, b"body")?;
    }

    // A FIN segment completes a Content-Length response and then carries a
    // complete close-delimited response.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_523);
        connection.client(b"GET /a HTTP/1.1\r\nHost: h\r\n\r\n")?;
        connection.client(b"GET /b HTTP/1.1\r\nHost: h\r\n\r\n")?;
        let header = b"HTTP/1.1 200 OK\r\nContent-Length: 10\r\n\r\n";
        let mut first = header.to_vec();
        first.extend_from_slice(b"12345");
        connection.server(&first)?;
        let mut tail = b"67890".to_vec();
        tail.extend_from_slice(b"HTTP/1.1 200 OK\r\n\r\nclose-body");
        let sequence =
            5000_u32.saturating_add(u32::try_from(header.len()).unwrap_or(0).saturating_add(5));
        connection.server_fin_at(sequence, &tail)?;
    }

    // Two responses in one segment: the second follows the first PDU.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_524);
        connection.client(b"GET /a HTTP/1.1\r\nHost: h\r\n\r\n")?;
        connection.client(b"GET /b HTTP/1.1\r\nHost: h\r\n\r\n")?;
        let mut both = b"HTTP/1.1 200 OK\r\nContent-Length: 3\r\n\r\naaa".to_vec();
        both.extend_from_slice(b"HTTP/1.1 200 OK\r\nContent-Length: 3\r\n\r\nbbb");
        connection.server(&both)?;
        connection.server_fin(b"")?;
    }

    // Two identical tails cover the same incomplete body bytes.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_525);
        connection.client(b"GET /tails HTTP/1.1\r\nHost: h\r\n\r\n")?;
        let header = b"HTTP/1.1 200 OK\r\nContent-Length: 8\r\n\r\n";
        let mut first = header.to_vec();
        first.extend_from_slice(b"abc");
        connection.server(&first)?;
        connection.server(b"def")?;
        let tail = 5000_u32
            .saturating_add(u32::try_from(header.len()).unwrap_or(0))
            .saturating_add(3);
        connection.server_at(tail, b"def")?;
        connection.server_fin(b"")?;
    }

    // A conflicting overlap still marks the segment as illegal.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_526);
        connection.client(b"GET /conflict HTTP/1.1\r\nHost: h\r\n\r\n")?;
        let header = b"HTTP/1.1 200 OK\r\nContent-Length: 6\r\n\r\n";
        let mut first = header.to_vec();
        first.extend_from_slice(b"abc");
        connection.server(&first)?;
        let overlap = 5000_u32.saturating_add(u32::try_from(header.len()).unwrap_or(0));
        connection.server_at(overlap, b"xyz")?;
        connection.server(b"def")?;
        connection.server_fin(b"")?;
    }

    // A truncated chunked body completed by FIN keeps its complete prefix.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_527);
        connection.client(b"GET /chunk-fin HTTP/1.1\r\nHost: h\r\n\r\n")?;
        connection.server(b"HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n5\r\nhel")?;
        connection.server_fin(b"lo\r\n")?;
    }

    // A chunk whose data is incomplete at FIN exports nothing.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_528);
        connection.client(b"GET /chunk-cut HTTP/1.1\r\nHost: h\r\n\r\n")?;
        connection.server(b"HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n5\r\nhel")?;
        connection.server_fin(b"")?;
    }

    // A request line with an extra token, which is still accepted.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_529);
        connection.client(b"GET /x HTTP/1.1 extra\r\nHost: h\r\n\r\n")?;
        connection.server(b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nxx")?;
        connection.server_fin(b"")?;
    }

    // A short status code, which is still accepted.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_530);
        connection.client(b"GET /x HTTP/1.1\r\nHost: h\r\n\r\n")?;
        connection.server(b"HTTP/1.1 20 OK\r\nContent-Length: 2\r\n\r\nxx")?;
        connection.server_fin(b"")?;
    }

    // A CONNECT 2xx tunnel carried in the response segment exports as the
    // CONNECT request object; a tunnel in a later segment does not.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_532);
        connection.client(b"CONNECT example.com:443 HTTP/1.1\r\nHost: h\r\n\r\n")?;
        let mut data = b"HTTP/1.1 200 Connection established\r\n\r\n".to_vec();
        data.extend_from_slice(b"tunnel!!");
        connection.server(&data)?;
        connection.server_fin(b"")?;
    }
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_533);
        connection.client(b"CONNECT example.com:443 HTTP/1.1\r\nHost: h\r\n\r\n")?;
        connection.server(b"HTTP/1.1 200 Connection established\r\n\r\n")?;
        connection.server(b"tunnel!!")?;
        connection.server_fin(b"")?;
    }

    // A response split exactly after the nine-byte `HTTP/1.1 ` prefix.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_534);
        connection.client(b"GET /split9a HTTP/1.1\r\nHost: h\r\n\r\n")?;
        let response = b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nxx";
        connection.server(response.get(..9).unwrap_or(&[]))?;
        connection.server(response.get(9..).unwrap_or(&[]))?;
        connection.server_fin(b"")?;
    }
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_535);
        connection.client(b"GET /split9b HTTP/1.1\r\nHost: h\r\n\r\n")?;
        let response = b"HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n2\r\nxx\r\n0\r\n\r\n";
        connection.server(response.get(..9).unwrap_or(&[]))?;
        connection.server(response.get(9..).unwrap_or(&[]))?;
        connection.server_fin(b"")?;
    }

    // An unusable chunk size terminates the chunked entity: the response
    // exports as an empty object named from the request.
    {
        let mut connection = ObjectConnection::new(&mut frames, 40_536);
        connection.client(b"GET /badchunk HTTP/1.1\r\nHost: h\r\n\r\n")?;
        connection.server(b"HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\nzz\r\n")?;
        connection.server_fin(b"")?;
    }
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

/// Payload of the large HTTP fixtures: deterministic binary, not compressible
/// into a trivial body.
const HTTP_LARGE_BODY_BYTES: usize = 4 * 1024 * 1024;

fn http_large_body() -> Vec<u8> {
    http_pattern_body(HTTP_LARGE_BODY_BYTES)
}

/// Deterministic binary body of `bytes` octets for a generated capture.
fn http_pattern_body(bytes: usize) -> Vec<u8> {
    (0..bytes)
        .map(|index| {
            let index = u32::try_from(index & 0xff_ffff).unwrap_or(0);
            index.wrapping_mul(31).wrapping_add(7) as u8
        })
        .collect()
}

/// A chunked response whose de-chunked body is `bytes` octets.
///
/// The chunk pattern restarts at each 1,460-byte chunk, matching the
/// generated load fixture whose export digest is stored in the regression
/// tool.
fn chunked_load_response(bytes: usize) -> Vec<u8> {
    let mut response = b"HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\nContent-Type: application/octet-stream\r\n\r\n".to_vec();
    let mut left = bytes;
    while left > 0 {
        let size = left.min(1460);
        response.extend_from_slice(format!("{size:x}\r\n").as_bytes());
        for index in 0..size {
            response.push(index.wrapping_mul(31).wrapping_add(7) as u8);
        }
        response.extend_from_slice(b"\r\n");
        left -= size;
    }
    response.extend_from_slice(b"0\r\n\r\n");
    response
}

/// Build a 64 MiB-class plain or chunked HTTP object capture.
pub fn build_http_load_capture(body_bytes: usize, chunked: bool) -> Result<Vec<u8>, String> {
    let mut frames = Vec::new();
    let mut client_sequence = 30_000_u32;
    let mut server_sequence = 70_000_u32;
    http_objects_push(
        T20_CLIENT,
        T20_SERVER,
        40_000,
        80,
        &mut client_sequence,
        b"GET /large.bin HTTP/1.1\r\nHost: h\r\n\r\n",
        &mut frames,
    )?;
    let response = if chunked {
        chunked_load_response(body_bytes)
    } else {
        http_large_response(&http_pattern_body(body_bytes))
    };
    for chunk in response.chunks(1460) {
        http_objects_push(
            T20_SERVER,
            T20_CLIENT,
            80,
            40_000,
            &mut server_sequence,
            chunk,
            &mut frames,
        )?;
    }
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

/// Build a 64 MiB-class decrypted-TLS HTTP object capture.
///
/// Returns the capture and its key log. The body is all `0x41`, matching the
/// recorded export digest for the TLS load case.
pub fn build_tls_load_capture(body_bytes: usize) -> Result<(Vec<u8>, Vec<u8>), String> {
    let mut writer = tls::Tls12Writer::new(0xc030, false);
    let session_id = [0x92_u8; 32];
    let body = vec![b'A'; body_bytes];
    let response = http_large_response(&body);
    let exchanges = tls12_large_exchanges(
        &mut writer,
        &session_id,
        b"GET /large-tls.bin HTTP/1.1\r\nHost: tls.test\r\n\r\n",
        &response,
    );
    let frames = tls_frames_segmented(443, 40_000, &exchanges)?;
    let capture = link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)?;
    Ok((capture, writer.keylog().into_bytes()))
}

fn http_large_response(body: &[u8]) -> Vec<u8> {
    let mut response = format!(
        "HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Length: {}\r\n\r\n",
        body.len()
    )
    .into_bytes();
    response.extend_from_slice(body);
    response
}

fn build_http_objects_large() -> Result<Vec<u8>, String> {
    let mut frames = Vec::new();
    let mut client_sequence = 30_000_u32;
    let mut server_sequence = 70_000_u32;
    http_objects_push(
        T20_CLIENT,
        T20_SERVER,
        40_000,
        80,
        &mut client_sequence,
        b"GET /large.bin HTTP/1.1\r\nHost: h\r\n\r\n",
        &mut frames,
    )?;
    let body = http_large_body();
    let response = http_large_response(&body);
    for chunk in response.chunks(1460) {
        http_objects_push(
            T20_SERVER,
            T20_CLIENT,
            80,
            40_000,
            &mut server_sequence,
            chunk,
            &mut frames,
        )?;
    }
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

fn tls12_large_exchanges(
    writer: &mut tls::Tls12Writer,
    session_id: &[u8],
    request: &[u8],
    response: &[u8],
) -> Vec<(bool, Vec<u8>)> {
    let (hello, server) = tls12_hellos(writer, session_id, None, false);
    let mut exchanges = vec![
        (true, tls::plain_record(tls::HANDSHAKE, 0x0301, &hello)),
        (false, tls::plain_record(tls::HANDSHAKE, 0x0303, &server)),
        (
            false,
            tls::plain_record(tls::CHANGE_CIPHER_SPEC, 0x0303, &[1]),
        ),
        (
            false,
            writer.record(false, tls::HANDSHAKE, &tls::handshake(20, &[0xaa; 12])),
        ),
        (
            true,
            tls::plain_record(tls::CHANGE_CIPHER_SPEC, 0x0303, &[1]),
        ),
        (
            true,
            writer.record(true, tls::HANDSHAKE, &tls::handshake(20, &[0xbb; 12])),
        ),
        (true, writer.record(true, tls::APPLICATION_DATA, request)),
    ];
    // TLSPlaintext.length is at most 2^14 bytes (RFC 8446 section 5.2), so
    // the multi-MiB body spans many records, each split into TCP segments.
    for chunk in response.chunks(16_384) {
        exchanges.push((false, writer.record(false, tls::APPLICATION_DATA, chunk)));
    }
    exchanges
}

fn tls_frames_segmented(
    port: u16,
    client_port: u16,
    payloads: &[(bool, Vec<u8>)],
) -> Result<Vec<Vec<u8>>, String> {
    let chunked: Vec<(bool, Vec<Vec<u8>>)> = payloads
        .iter()
        .map(|(from_client, payload)| {
            (
                *from_client,
                payload.chunks(1460).map(<[u8]>::to_vec).collect(),
            )
        })
        .collect();
    tls_frames_chunked(port, client_port, &chunked)
}

fn build_tls12_gcm_large() -> Result<Vec<u8>, String> {
    let mut writer = tls::Tls12Writer::new(0xc030, false);
    let session_id = [0x92_u8; 32];
    let body = http_large_body();
    let response = http_large_response(&body);
    let exchanges = tls12_large_exchanges(
        &mut writer,
        &session_id,
        b"GET /large-tls.bin HTTP/1.1\r\nHost: tls.test\r\n\r\n",
        &response,
    );
    let frames = tls_frames_segmented(443, 40_000, &exchanges)?;
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

fn build_tls12_gcm_large_keys() -> Result<Vec<u8>, String> {
    Ok(tls::Tls12Writer::new(0xc030, false).keylog().into_bytes())
}

fn tls_frames_from(
    port: u16,
    client_port: u16,
    payloads: &[(bool, Vec<u8>)],
) -> Result<Vec<Vec<u8>>, String> {
    let chunked: Vec<(bool, Vec<Vec<u8>>)> = payloads
        .iter()
        .map(|(from_client, payload)| (*from_client, vec![payload.clone()]))
        .collect();
    tls_frames_chunked(port, client_port, &chunked)
}

fn tls_frames_chunked(
    port: u16,
    client_port: u16,
    payloads: &[(bool, Vec<Vec<u8>>)],
) -> Result<Vec<Vec<u8>>, String> {
    let mut client_sequence = 1000_u32;
    let mut server_sequence = 5000_u32;
    let mut frames = Vec::new();
    for (from_client, chunks) in payloads {
        for payload in chunks {
            if *from_client {
                frames.push(tcp_payload_between(
                    T20_CLIENT,
                    T20_SERVER,
                    client_port,
                    port,
                    client_sequence,
                    1,
                    payload,
                )?);
                client_sequence = client_sequence
                    .saturating_add(u32::try_from(payload.len()).unwrap_or(u32::MAX));
            } else {
                frames.push(tcp_payload_between(
                    T20_SERVER,
                    T20_CLIENT,
                    port,
                    client_port,
                    server_sequence,
                    1,
                    payload,
                )?);
                server_sequence = server_sequence
                    .saturating_add(u32::try_from(payload.len()).unwrap_or(u32::MAX));
            }
        }
    }
    Ok(frames)
}

/// Split selected exchanges into the given byte-boundary chunks.
fn split_tls_exchanges(
    payloads: &[(bool, Vec<u8>)],
    splits: &[(usize, &[usize])],
) -> Vec<(bool, Vec<Vec<u8>>)> {
    payloads
        .iter()
        .enumerate()
        .map(|(index, (from_client, payload))| {
            let boundaries = splits
                .iter()
                .find(|(target, _)| *target == index)
                .map(|(_, boundaries)| *boundaries);
            let chunks = match boundaries {
                Some(boundaries) => {
                    let mut chunks = Vec::new();
                    let mut start = 0_usize;
                    for boundary in boundaries
                        .iter()
                        .copied()
                        .chain(std::iter::once(payload.len()))
                    {
                        let boundary = boundary.min(payload.len());
                        if boundary > start
                            && let Some(chunk) = payload.get(start..boundary)
                        {
                            chunks.push(chunk.to_vec());
                        }
                        start = boundary;
                    }
                    chunks
                }
                None => vec![payload.clone()],
            };
            (*from_client, chunks)
        })
        .collect()
}

fn tls_exchange_split(
    port: u16,
    payloads: &[(bool, Vec<u8>)],
    splits: &[(usize, &[usize])],
) -> Result<Vec<u8>, String> {
    let chunked = split_tls_exchanges(payloads, splits);
    let frames = tls_frames_chunked(port, 40_000, &chunked)?;
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

fn tls_sni(name: &[u8]) -> Vec<u8> {
    let mut list = vec![0x00];
    list.extend_from_slice(&tls_vector(name));
    tls_vector(&list)
}

fn tls_client_key_share() -> Vec<u8> {
    let mut exchange = 0x001d_u16.to_be_bytes().to_vec();
    exchange.extend_from_slice(&32_u16.to_be_bytes());
    exchange.extend_from_slice(&[0x71; 32]);
    let mut body = u16::try_from(exchange.len())
        .unwrap_or(u16::MAX)
        .to_be_bytes()
        .to_vec();
    body.extend_from_slice(&exchange);
    body
}

fn tls_server_key_share() -> Vec<u8> {
    let mut body = 0x001d_u16.to_be_bytes().to_vec();
    body.extend_from_slice(&32_u16.to_be_bytes());
    body.extend_from_slice(&[0x72; 32]);
    body
}

fn tls13_hellos(writer: &tls::Tls13Writer) -> (Vec<u8>, Vec<u8>) {
    let suite = writer.suite_id();
    let mut ciphers = vec![suite, 0x1301, 0x1302, 0x1303, 0xc02f];
    ciphers.dedup();
    let supported_versions = vec![4, 0x03, 0x04, 0x03, 0x03];
    let mut client_extensions = vec![
        (0, tls_sni(b"tls.test")),
        (10, tls_vector(&[0x00, 0x1d, 0x00, 0x17])),
        (13, tls_vector(&[0x04, 0x03, 0x08, 0x04])),
        (16, {
            let mut alpn = vec![2, b'h', b'1'];
            let mut body = u16::try_from(alpn.len())
                .unwrap_or(0)
                .to_be_bytes()
                .to_vec();
            body.append(&mut alpn);
            body
        }),
        (43, supported_versions),
        (51, tls_client_key_share()),
    ];
    if writer.has_early() {
        client_extensions.push((42, Vec::new()));
    }
    let hello = tls::client_hello(
        tls::TLS12_VERSION,
        writer.client_random(),
        &[],
        &ciphers,
        &client_extensions,
    );
    let server_extensions = [(43, vec![0x03, 0x04]), (51, tls_server_key_share())];
    let server = tls::server_hello(
        tls::TLS12_VERSION,
        writer.server_random(),
        &[],
        suite,
        &server_extensions,
    );
    (hello, server)
}

fn build_tls13_flow(suite_id: u16, extra_alert: bool) -> Result<Vec<u8>, String> {
    let mut writer = tls::Tls13Writer::new(suite_id);
    let verify_len: usize = if suite_id == 0x1302 { 48 } else { 32 };
    let (hello, server) = tls13_hellos(&writer);
    let request = b"GET /hello HTTP/1.1\r\nHost: tls.test\r\n\r\n".to_vec();
    let response = b"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nhello".to_vec();
    let exchanges = vec![
        (true, tls::plain_record(tls::HANDSHAKE, 0x0301, &hello)),
        (false, tls::plain_record(tls::HANDSHAKE, 0x0303, &server)),
        (
            false,
            tls::plain_record(tls::CHANGE_CIPHER_SPEC, 0x0303, &[1]),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(8, &[]),
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(20, &vec![0xaa; verify_len]),
            ),
        ),
        (
            true,
            tls::plain_record(tls::CHANGE_CIPHER_SPEC, 0x0303, &[1]),
        ),
        (
            true,
            writer.record(
                true,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(20, &vec![0xbb; verify_len]),
            ),
        ),
        (
            true,
            writer.record(
                true,
                tls::Epoch::Application,
                tls::APPLICATION_DATA,
                &request,
            ),
        ),
        {
            let mut record = writer.record(
                false,
                tls::Epoch::Application,
                tls::APPLICATION_DATA,
                &response,
            );
            if extra_alert {
                record.extend_from_slice(&writer.record(
                    false,
                    tls::Epoch::Application,
                    tls::ALERT,
                    &[1, 0],
                ));
            }
            (false, record)
        },
    ];
    tls_exchange(443, &exchanges)
}

fn build_tls13(suite_id: u16) -> Result<Vec<u8>, String> {
    build_tls13_flow(suite_id, false)
}

fn build_tls13_two_records() -> Result<Vec<u8>, String> {
    build_tls13_flow(0x1301, true)
}

fn build_tls13_keys(suite_id: u16) -> Result<Vec<u8>, String> {
    Ok(tls::Tls13Writer::new(suite_id).keylog().into_bytes())
}

fn build_tls13_keyupdate() -> Result<Vec<u8>, String> {
    let verify_len = 48_u8;
    let mut writer = tls::Tls13Writer::new(0x1302);
    let (hello, server) = tls13_hellos(&writer);
    let request = b"GET /before HTTP/1.1\r\nHost: tls.test\r\n\r\n".to_vec();
    let response = b"HTTP/1.1 200 OK\r\nContent-Length: 6\r\n\r\nbefore".to_vec();
    let request2 = b"GET /after HTTP/1.1\r\nHost: tls.test\r\n\r\n".to_vec();
    let response2 = b"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nafter".to_vec();
    let mut exchanges = vec![
        (true, tls::plain_record(tls::HANDSHAKE, 0x0301, &hello)),
        (false, tls::plain_record(tls::HANDSHAKE, 0x0303, &server)),
        (
            false,
            tls::plain_record(tls::CHANGE_CIPHER_SPEC, 0x0303, &[1]),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(8, &[]),
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(20, &vec![0xaa; usize::from(verify_len)]),
            ),
        ),
        (
            true,
            tls::plain_record(tls::CHANGE_CIPHER_SPEC, 0x0303, &[1]),
        ),
        (
            true,
            writer.record(
                true,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(20, &vec![0xbb; usize::from(verify_len)]),
            ),
        ),
        (
            true,
            writer.record(
                true,
                tls::Epoch::Application,
                tls::APPLICATION_DATA,
                &request,
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Application,
                tls::APPLICATION_DATA,
                &response,
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Application,
                tls::HANDSHAKE,
                &tls::handshake(24, &[0]),
            ),
        ),
    ];
    writer.key_update(false);
    exchanges.push((
        true,
        writer.record(
            true,
            tls::Epoch::Application,
            tls::APPLICATION_DATA,
            &request2,
        ),
    ));
    exchanges.push((
        false,
        writer.record(
            false,
            tls::Epoch::Application,
            tls::APPLICATION_DATA,
            &response2,
        ),
    ));
    tls_exchange(443, &exchanges)
}

fn build_tls13_early() -> Result<Vec<u8>, String> {
    let verify_len = 48_u8;
    let mut writer = tls::Tls13Writer::new(0x1302);
    writer.with_early();
    let (hello, server) = tls13_hellos(&writer);
    let early = b"GET /early HTTP/1.1\r\nHost: tls.test\r\n\r\n".to_vec();
    let response = b"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nearly".to_vec();
    let mut first = tls::plain_record(tls::HANDSHAKE, 0x0301, &hello);
    first.extend_from_slice(&tls::plain_record(tls::CHANGE_CIPHER_SPEC, 0x0303, &[1]));
    first.extend_from_slice(&writer.record(true, tls::Epoch::Early, tls::APPLICATION_DATA, &early));
    let exchanges = vec![
        (true, first),
        (false, tls::plain_record(tls::HANDSHAKE, 0x0303, &server)),
        (
            false,
            tls::plain_record(tls::CHANGE_CIPHER_SPEC, 0x0303, &[1]),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(8, &[]),
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(20, &vec![0xaa; usize::from(verify_len)]),
            ),
        ),
        (
            true,
            tls::plain_record(tls::CHANGE_CIPHER_SPEC, 0x0303, &[1]),
        ),
        (
            true,
            writer.record(
                true,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(20, &vec![0xbb; usize::from(verify_len)]),
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Application,
                tls::APPLICATION_DATA,
                &response,
            ),
        ),
    ];
    tls_exchange(443, &exchanges)
}

/// TLS 1.3 without middlebox CCS, with one plaintext record after ServerHello.
fn build_tls13_plaintext_spoof(alert: bool) -> Result<Vec<u8>, String> {
    let mut writer = tls::Tls13Writer::new(0x1301);
    let (hello, server) = tls13_hellos(&writer);
    let spoof = if alert {
        tls::plain_record(tls::ALERT, 0x0303, &[2, 40])
    } else {
        tls::plain_record(tls::HANDSHAKE, 0x0303, &tls::handshake(24, &[1]))
    };
    let exchanges = vec![
        (true, tls::plain_record(tls::HANDSHAKE, 0x0301, &hello)),
        (false, tls::plain_record(tls::HANDSHAKE, 0x0303, &server)),
        (false, spoof),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(8, &[]),
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(20, &[0xaa; 32]),
            ),
        ),
        (
            true,
            writer.record(
                true,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(20, &[0xbb; 32]),
            ),
        ),
        (
            true,
            writer.record(
                true,
                tls::Epoch::Application,
                tls::APPLICATION_DATA,
                b"GET /spoof HTTP/1.1\r\nHost: tls.test\r\n\r\n",
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Application,
                tls::APPLICATION_DATA,
                b"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nhello",
            ),
        ),
    ];
    tls_exchange(443, &exchanges)
}

fn build_tls13_close_delimited() -> Result<Vec<u8>, String> {
    let mut writer = tls::Tls13Writer::new(0x1301);
    let (hello, server) = tls13_hellos(&writer);
    let exchanges = vec![
        (true, tls::plain_record(tls::HANDSHAKE, 0x0301, &hello)),
        (false, tls::plain_record(tls::HANDSHAKE, 0x0303, &server)),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(8, &[]),
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(20, &[0xaa; 32]),
            ),
        ),
        (
            true,
            writer.record(
                true,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(20, &[0xbb; 32]),
            ),
        ),
        (
            true,
            writer.record(
                true,
                tls::Epoch::Application,
                tls::APPLICATION_DATA,
                b"GET /close HTTP/1.1\r\nHost: tls.test\r\n\r\n",
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Application,
                tls::APPLICATION_DATA,
                b"HTTP/1.1 200 OK\r\nConnection: close\r\n\r\nhello there",
            ),
        ),
    ];
    let server_sequence = exchanges
        .iter()
        .filter(|(from_client, _)| !*from_client)
        .map(|(_, payload)| payload.len())
        .sum::<usize>();
    let mut frames = tls_frames_from(443, 40_000, &exchanges)?;
    frames.push(tcp_fin_empty_between(
        T20_SERVER,
        T20_CLIENT,
        443,
        40_000,
        5000_u32.saturating_add(u32::try_from(server_sequence).unwrap_or(u32::MAX)),
        1,
    )?);
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

