fn build_tls13_hrr_spoof() -> Result<Vec<u8>, String> {
    let mut writer = tls::Tls13Writer::new(0x1301);
    let (hello, _) = tls13_hellos(&writer);
    let hrr = tls::server_hello(
        tls::TLS12_VERSION,
        tls::HELLO_RETRY_REQUEST_RANDOM,
        &[],
        writer.suite_id(),
        &[(43, vec![0x03, 0x04]), (51, vec![0x00, 0x1d])],
    );
    let mut spoof_hello = hello.clone();
    if let Some(random) = spoof_hello.get_mut(6..38) {
        random.fill(0x99);
    }
    let exchanges = vec![
        (true, tls::plain_record(tls::HANDSHAKE, 0x0301, &hello)),
        (false, tls::plain_record(tls::HANDSHAKE, 0x0303, &hrr)),
        (
            true,
            tls::plain_record(tls::HANDSHAKE, 0x0303, &spoof_hello),
        ),
        (false, tls::plain_record(tls::ALERT, 0x0303, &[2, 40])),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(8, &[]),
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(20, &[0xaa; 32]),
            ),
        ),
        (
            true,
            writer.record(
                true,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(20, &[0xbb; 32]),
            ),
        ),
    ];
    tls_exchange(443, &exchanges)
}

fn build_tls13_split() -> Result<Vec<u8>, String> {
    let mut writer = tls::Tls13Writer::new(0x1301);
    let (hello, server) = tls13_hellos(&writer);
    let server_finished = tls::handshake(20, &[0xaa; 32]);
    let client_finished = tls::handshake(20, &[0xbb; 32]);
    let request = b"GET /split HTTP/1.1\r\nHost: tls.test\r\n\r\n".to_vec();
    let response = b"HTTP/1.1 200 OK\r\nContent-Length: 11\r\n\r\nhello split".to_vec();
    let exchanges = vec![
        (true, tls::plain_record(tls::HANDSHAKE, 0x0301, &hello)),
        (false, tls::plain_record(tls::HANDSHAKE, 0x0303, &server)),
        (
            false,
            tls::plain_record(tls::CHANGE_CIPHER_SPEC, 0x0303, &[1]),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(8, &[]),
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                server_finished.get(..15).unwrap_or(&server_finished),
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                server_finished.get(15..).unwrap_or_default(),
            ),
        ),
        (
            true,
            tls::plain_record(tls::CHANGE_CIPHER_SPEC, 0x0303, &[1]),
        ),
        (
            true,
            writer.record(
                true,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                client_finished.get(..10).unwrap_or(&client_finished),
            ),
        ),
        (
            true,
            writer.record(
                true,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                client_finished.get(10..).unwrap_or_default(),
            ),
        ),
        (
            true,
            writer.record(
                true,
                tls::Epoch::Application,
                tls::APPLICATION_DATA,
                request.get(..12).unwrap_or(&request),
            ),
        ),
        (
            true,
            writer.record(
                true,
                tls::Epoch::Application,
                tls::APPLICATION_DATA,
                request.get(12..).unwrap_or_default(),
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Application,
                tls::APPLICATION_DATA,
                response.get(..15).unwrap_or(&response),
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Application,
                tls::APPLICATION_DATA,
                response.get(15..30).unwrap_or_default(),
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Application,
                tls::APPLICATION_DATA,
                response.get(30..).unwrap_or_default(),
            ),
        ),
    ];
    tls_exchange_split(
        443,
        &exchanges,
        &[(0, &[20]), (4, &[3]), (7, &[2]), (8, &[5]), (11, &[2])],
    )
}

fn build_tls13_keyupdate_split() -> Result<Vec<u8>, String> {
    let mut writer = tls::Tls13Writer::new(0x1302);
    let (hello, server) = tls13_hellos(&writer);
    let key_update = tls::handshake(24, &[0]);
    let response = b"HTTP/1.1 200 OK\r\nContent-Length: 6\r\n\r\nbefore".to_vec();
    let request2 = b"GET /after HTTP/1.1\r\nHost: tls.test\r\n\r\n".to_vec();
    let response2 = b"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nafter".to_vec();
    let mut exchanges = vec![
        (true, tls::plain_record(tls::HANDSHAKE, 0x0301, &hello)),
        (false, tls::plain_record(tls::HANDSHAKE, 0x0303, &server)),
        (
            false,
            tls::plain_record(tls::CHANGE_CIPHER_SPEC, 0x0303, &[1]),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(8, &[]),
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(20, &[0xaa; 32]),
            ),
        ),
        (
            true,
            tls::plain_record(tls::CHANGE_CIPHER_SPEC, 0x0303, &[1]),
        ),
        (
            true,
            writer.record(
                true,
                tls::Epoch::Handshake,
                tls::HANDSHAKE,
                &tls::handshake(20, &[0xbb; 32]),
            ),
        ),
        (
            true,
            writer.record(
                true,
                tls::Epoch::Application,
                tls::APPLICATION_DATA,
                b"GET /before HTTP/1.1\r\nHost: tls.test\r\n\r\n",
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Application,
                tls::APPLICATION_DATA,
                &response,
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Application,
                tls::HANDSHAKE,
                key_update.get(..2).unwrap_or(&key_update),
            ),
        ),
        (
            false,
            writer.record(
                false,
                tls::Epoch::Application,
                tls::HANDSHAKE,
                key_update.get(2..).unwrap_or_default(),
            ),
        ),
    ];
    writer.key_update(false);
    exchanges.push((
        true,
        writer.record(
            true,
            tls::Epoch::Application,
            tls::APPLICATION_DATA,
            request2.get(..10).unwrap_or(&request2),
        ),
    ));
    exchanges.push((
        true,
        writer.record(
            true,
            tls::Epoch::Application,
            tls::APPLICATION_DATA,
            request2.get(10..).unwrap_or_default(),
        ),
    ));
    exchanges.push((
        false,
        writer.record(
            false,
            tls::Epoch::Application,
            tls::APPLICATION_DATA,
            response2.get(..12).unwrap_or(&response2),
        ),
    ));
    exchanges.push((
        false,
        writer.record(
            false,
            tls::Epoch::Application,
            tls::APPLICATION_DATA,
            response2.get(12..).unwrap_or_default(),
        ),
    ));
    tls_exchange_split(443, &exchanges, &[(9, &[1]), (12, &[4]), (14, &[3])])
}

