/// TLS edge cases: a handshake split across records, HelloRetryRequest,
/// empty records, an invalid heartbeat and a one-byte alert.
fn tls_hrr() -> Vec<u8> {
    let mut body = 0x0303_u16.to_be_bytes().to_vec();
    body.extend_from_slice(&[
        0xcf, 0x21, 0xad, 0x74, 0xe5, 0x9a, 0x61, 0x11, 0xbe, 0x1d, 0x8c, 0x02, 0x1e, 0x65, 0xb8,
        0x91, 0xc2, 0xa2, 0x11, 0x16, 0x7a, 0xbb, 0x8c, 0x5e, 0x07, 0x9e, 0x09, 0xe2, 0xc8, 0xa8,
        0x33, 0x9c,
    ]);
    body.push(0);
    body.extend_from_slice(&0x1301_u16.to_be_bytes());
    body.push(0);
    let mut extensions = Vec::new();
    extensions.extend_from_slice(&tls_extension(43, &[0x03, 0x04]));
    extensions.extend_from_slice(&tls_extension(51, &0x001d_u16.to_be_bytes()));
    body.extend_from_slice(
        &u16::try_from(extensions.len())
            .unwrap_or(u16::MAX)
            .to_be_bytes(),
    );
    body.extend_from_slice(&extensions);
    tls_handshake(2, &body)
}

fn build_tls_edge() -> Result<Vec<u8>, String> {
    let hello = tls20_client_hello();
    let split = 60_usize.min(hello.len());
    let mut split_records = tls_record_pdu(22, 0x0301, hello.get(..split).unwrap_or(&[]));
    split_records.extend_from_slice(&tls_record_pdu(
        22,
        0x0301,
        hello.get(split..).unwrap_or(&[]),
    ));
    let hrr = tls_record_pdu(22, 0x0303, &tls_hrr());
    let cross_first = tls_record_pdu(22, 0x0301, hello.get(..split).unwrap_or(&[]));
    let cross_second = tls_record_pdu(22, 0x0301, hello.get(split..).unwrap_or(&[]));
    let frames = vec![
        tcp_payload_between(T20_CLIENT, T20_SERVER, 40_120, 443, 1000, 1, &split_records)?,
        tcp_payload_between(T20_CLIENT, T20_SERVER, 40_121, 443, 1000, 1, &hrr)?,
        tcp_payload_between(
            T20_CLIENT,
            T20_SERVER,
            40_122,
            443,
            1000,
            1,
            &tls_record_pdu(21, 0x0303, &[]),
        )?,
        tcp_payload_between(
            T20_CLIENT,
            T20_SERVER,
            40_123,
            443,
            1000,
            1,
            &tls_record_pdu(23, 0x0303, &[]),
        )?,
        tcp_payload_between(
            T20_CLIENT,
            T20_SERVER,
            40_124,
            443,
            1000,
            1,
            &tls_record_pdu(20, 0x0303, &[]),
        )?,
        tcp_payload_between(
            T20_CLIENT,
            T20_SERVER,
            40_125,
            443,
            1000,
            1,
            &tls_record_pdu(24, 0x0303, &[0xaa, 0xbb]),
        )?,
        tcp_payload_between(
            T20_CLIENT,
            T20_SERVER,
            40_126,
            443,
            1000,
            1,
            &tls_record_pdu(21, 0x0303, &[0x02]),
        )?,
        tcp_payload_between(T20_CLIENT, T20_SERVER, 40_127, 443, 1000, 1, &cross_first)?,
        tcp_payload_between(
            T20_CLIENT,
            T20_SERVER,
            40_127,
            443,
            1000_u32.saturating_add(u32::try_from(cross_first.len()).unwrap_or(u32::MAX)),
            1,
            &cross_second,
        )?,
        tcp_payload_between(
            T20_CLIENT,
            T20_SERVER,
            40_128,
            443,
            1000,
            1,
            &tls_record_pdu(22, 0x0301, hello.get(..split).unwrap_or(&[])),
        )?,
        tcp_payload_between(
            T20_SERVER,
            T20_CLIENT,
            443,
            40_128,
            5000,
            1,
            &tls_record_pdu(22, 0x0303, &tls_server_hello()),
        )?,
    ];
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

fn build_http1_edge() -> Result<Vec<u8>, String> {
    let mut client_sequence = 1000_u32;
    let mut server_sequence = 5000_u32;
    let mut frames = Vec::new();
    let mut push_client = |payload: &[u8], frames: &mut Vec<Vec<u8>>| -> Result<(), String> {
        frames.push(tcp_payload_between(
            T20_CLIENT,
            T20_SERVER,
            40_130,
            80,
            client_sequence,
            1,
            payload,
        )?);
        client_sequence =
            client_sequence.saturating_add(u32::try_from(payload.len()).unwrap_or(u32::MAX));
        Ok(())
    };
    let mut push_server = |payload: &[u8], frames: &mut Vec<Vec<u8>>| -> Result<(), String> {
        frames.push(tcp_payload_between(
            T20_SERVER,
            T20_CLIENT,
            80,
            40_130,
            server_sequence,
            1,
            payload,
        )?);
        server_sequence =
            server_sequence.saturating_add(u32::try_from(payload.len()).unwrap_or(u32::MAX));
        Ok(())
    };
    push_client(b"HEAD /h HTTP/1.1\r\nHost: x\r\n\r\n", &mut frames)?;
    push_server(
        b"HTTP/1.1 200 OK\r\nContent-Length: 100\r\n\r\n",
        &mut frames,
    )?;
    push_client(b"GET /304 HTTP/1.1\r\nHost: x\r\n\r\n", &mut frames)?;
    push_server(
        b"HTTP/1.1 304 Not Modified\r\nContent-Length: 100\r\n\r\n",
        &mut frames,
    )?;
    push_server(
        b"HTTP/1.1 304 Not Modified\r\nContent-Length: 5\r\n\r\nabc",
        &mut frames,
    )?;
    push_client(
        b"POST /dup HTTP/1.1\r\nHost: x\r\nContent-Length: 3\r\nContent-Length: 5\r\n\r\nhello",
        &mut frames,
    )?;
    push_client(b"GET /chunk HTTP/1.1\r\nHost: x\r\n\r\n", &mut frames)?;
    push_server(
        b"HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n1\r\na\r\n0\r\nX: y\r\n\r\n",
        &mut frames,
    )?;
    push_client(
        b"CONNECT example.com:443 HTTP/1.1\r\nHost: x\r\n\r\n",
        &mut frames,
    )?;
    push_client(b"GET /bad HTTP/1.1\r\nHost x\r\n\r\n", &mut frames)?;
    push_client(
        b"GET /name HTTP/1.1\r\nBad Name: v\r\nHost: x\r\n\r\n",
        &mut frames,
    )?;
    frames.push(tcp_payload_between(
        T20_SERVER,
        T20_CLIENT,
        80,
        40_131,
        1000,
        1,
        b"HTTP/1.1 200 OK\r\nContent-Length: 3\r\nContent-Length: abc\r\n\r\nhello",
    )?);
    frames.push(tcp_payload_between(
        T20_SERVER,
        T20_CLIENT,
        80,
        40_132,
        1000,
        1,
        b"HTTP/1.1 200 OK\r\nContent-Length: abc\r\nContent-Length: 3\r\n\r\nhello",
    )?);
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

fn build_bgp_overlong() -> Result<Vec<u8>, String> {
    let mut payload = vec![0xff; 16];
    payload.extend_from_slice(&4097_u16.to_be_bytes());
    payload.push(4);
    payload.resize(4097, b'x');
    let mut after_valid = bgp_message(4, &[]);
    after_valid.extend_from_slice(payload.get(..19).unwrap_or(&[]));
    after_valid.extend_from_slice(payload.get(19..40).unwrap_or(&[]));
    let frames = vec![
        tcp_payload_between(T20_CLIENT, T20_SERVER, 40_140, 179, 1000, 1, &payload)?,
        tcp_payload_between(T20_CLIENT, T20_SERVER, 40_141, 179, 1000, 1, &after_valid)?,
    ];
    link_pcap(u32::from(LINKTYPE_ETHERNET), &frames)
}

