fn tls_record_pdu(content_type: u8, version: u16, body: &[u8]) -> Vec<u8> {
    let mut out = vec![content_type];
    out.extend_from_slice(&version.to_be_bytes());
    out.extend_from_slice(&u16::try_from(body.len()).unwrap_or(u16::MAX).to_be_bytes());
    out.extend_from_slice(body);
    out
}

fn tls20_client_hello() -> Vec<u8> {
    let mut body = 0x0303_u16.to_be_bytes().to_vec();
    body.extend_from_slice(&[0x11; 32]);
    body.push(32);
    body.extend_from_slice(&[0x22; 32]);
    let ciphers = [0x1301_u16, 0x1302, 0x1303, 0xc02b, 0xc02f];
    body.extend_from_slice(
        &u16::try_from(ciphers.len().saturating_mul(2))
            .unwrap_or(u16::MAX)
            .to_be_bytes(),
    );
    for cipher in ciphers {
        body.extend_from_slice(&cipher.to_be_bytes());
    }
    body.extend_from_slice(&[1, 0]);

    let mut sni = vec![0x00];
    sni.extend_from_slice(&tls_vector(b"example.com"));
    let mut alpn_body = Vec::new();
    alpn_body.extend_from_slice(&3_u16.to_be_bytes());
    alpn_body.extend_from_slice(&[2, b'h', b'2']);
    let mut signatures = Vec::new();
    for algorithm in [0x0403_u16, 0x0804, 0x0401] {
        signatures.extend_from_slice(&algorithm.to_be_bytes());
    }
    let mut groups = Vec::new();
    for group in [0x001d_u16, 0x0017, 0x0018] {
        groups.extend_from_slice(&group.to_be_bytes());
    }
    let versions = [0x0304_u16, 0x0303];
    let mut versions_body = vec![4];
    for version in versions {
        versions_body.extend_from_slice(&version.to_be_bytes());
    }
    let mut extensions = Vec::new();
    extensions.extend_from_slice(&tls_extension(0, &tls_vector(&sni)));
    extensions.extend_from_slice(&tls_extension(16, &alpn_body));
    extensions.extend_from_slice(&tls_extension(13, &tls_vector(&signatures)));
    extensions.extend_from_slice(&tls_extension(10, &tls_vector(&groups)));
    extensions.extend_from_slice(&tls_extension(11, &[3, 0, 1, 2]));
    extensions.extend_from_slice(&tls_extension(43, &versions_body));
    body.extend_from_slice(
        &u16::try_from(extensions.len())
            .unwrap_or(u16::MAX)
            .to_be_bytes(),
    );
    body.extend_from_slice(&extensions);
    tls_handshake(1, &body)
}

