fn extra_case_specs(name: &str) -> &'static [CaseSpec] {
    match name {
        "tcp-streams" => STATS_TCP_STREAM_CASES,
        "tcp-boundary" => STATS_TCP_BOUNDARY_CASES,
        "udp-prefixes" => STATS_UDP_PREFIXES_CASES,
        "udp-edge" => STATS_UDP_EDGE_CASES,
        "ipv4-truncated" => STATS_IPV4_TRUNCATED_CASES,
        "ethernet-malformed" => STATS_ETHERNET_MALFORMED_CASES,
        "icmp-error-tcp" => STATS_ICMP_ERROR_TCP_CASES,
        "icmp-error-udp" => STATS_ICMP_ERROR_UDP_CASES,
        "icmp-quoted-ipv6" => STATS_ICMP_QUOTED_IPV6_CASES,
        "icmp-quote-ipv6-ext" => STATS_ICMP_QUOTE_IPV6_EXT_CASES,
        "gre-tunnel" => STATS_TUNNEL_CASES,
        "vxlan-tunnel" => STATS_TUNNEL_CASES,
        "erspan-tunnel" => STATS_TUNNEL_CASES,
        "geneve-tunnel" => STATS_TUNNEL_CASES,
        "ip-tunnels" => STATS_TUNNEL_CASES,
        "ntp-client-server" => STATS_NTP_CASES,
        "stats-truncated-read" => STATS_TRUNCATED_READ_CASES,
        _ => &[],
    }
}

