fn stats_eth(source: [u8; 6], destination: [u8; 6], ethertype: u16, payload: &[u8]) -> Vec<u8> {
    let mut frame = Vec::with_capacity(14 + payload.len());
    frame.extend_from_slice(&destination);
    frame.extend_from_slice(&source);
    frame.extend_from_slice(&ethertype.to_be_bytes());
    frame.extend_from_slice(payload);
    frame
}

fn stats_udp4(
    source: [u8; 4],
    destination: [u8; 4],
    source_port: u16,
    destination_port: u16,
    payload: &[u8],
) -> Result<Vec<u8>, String> {
    let length = u16::try_from(8 + payload.len())
        .map_err(|_| "stats UDP payload does not fit".to_string())?;
    let segment = udp_segment(
        4,
        &source,
        &destination,
        UdpFields {
            source_port,
            destination_port,
            payload,
            length,
            ..Default::default()
        },
    );
    let datagram = ipv4_transport_between(source, destination, 17, &segment)?;
    Ok(stats_eth(SOURCE_MAC, DESTINATION_MAC, 0x0800, &datagram))
}

fn stats_udp6(
    source: [u8; 16],
    destination: [u8; 16],
    source_port: u16,
    destination_port: u16,
    payload: &[u8],
) -> Result<Vec<u8>, String> {
    let length = u16::try_from(8 + payload.len())
        .map_err(|_| "stats IPv6 UDP payload does not fit".to_string())?;
    let segment = udp_segment(
        6,
        &source,
        &destination,
        UdpFields {
            source_port,
            destination_port,
            payload,
            length,
            ..Default::default()
        },
    );
    let datagram = ipv6_packet(Ipv6Fields {
        next_header: 17,
        payload: &segment,
        payload_length: length,
        source,
        destination,
        ..Default::default()
    });
    Ok(stats_eth(SOURCE_MAC, DESTINATION_MAC, 0x86dd, &datagram))
}

fn stats_tcp4(
    source: [u8; 4],
    destination: [u8; 4],
    fields: TcpFields<'_>,
) -> Result<Vec<u8>, String> {
    let segment = tcp_segment(4, &source, &destination, fields);
    let datagram = ipv4_transport_between(source, destination, 6, &segment)?;
    Ok(stats_eth(SOURCE_MAC, DESTINATION_MAC, 0x0800, &datagram))
}

